/**
 * add-photos-layout-and-email-backend.js
 * Run from your project root:   node add-photos-layout-and-email-backend.js
 *
 * A lot in this one:
 *
 * 1. Journal gallery rebuilt to match FZShotit's layout exactly, checked
 *    the actual component from that project rather than guessing: an
 *    even grid, 2 columns on mobile, 3 on desktop, every image the same
 *    size sitting cleanly side by side. The old "wide" items that broke
 *    the rhythm are gone.
 *
 * 2. The Vogue photo's head-crop is fixed. The source photo was always
 *    fine, the issue was the container's aspect ratio being much wider
 *    than the photo, so a plain center-crop cut off the top. Repositioned
 *    it to keep the head and gele in frame.
 *
 * 3. Cropped your three screenshots into clean, usable photos (the X
 *    post, the Instagram story, the ceremony photo) and put them to work:
 *    the X post is now an "As Seen On X" callout next to the Ayra Starr
 *    story on Achievements, and the other two are in the Journal grid.
 *
 * 4. Added a fourth Achievements entry for the podcast feature, same
 *    video auto-discovery pattern as your other videos — drop a file
 *    into public/videos/podcast/ whenever you have the clip and it
 *    plays automatically, muted and looped. Until then the photo shows.
 *
 * 5. Contact and Booking forms now actually send real emails. This is
 *    the one that needs a small setup step from you:
 *
 *      a) Copy .env.local.example to a new file named .env.local
 *      b) Sign up free at https://resend.com (no card needed, 100
 *         emails/day free)
 *      c) Create an API key there and paste it into .env.local
 *      d) Put the email address YOU want to receive messages at into
 *         .env.local too
 *      e) Restart the dev server
 *
 *    Full details are inside .env.local.example itself. Until those two
 *    values are set, both forms fail gracefully with a clear message
 *    instead of pretending to succeed — confirmed this with real tests,
 *    not just written and hoped. Also added basic rate limiting (max 5
 *    submissions per IP per 10 minutes) so the forms cannot be spammed,
 *    confirmed that actually blocks a 6th rapid request too.
 *
 *    One thing worth knowing: the direct "hello@geleglamzzz.com" email
 *    link on the Contact page itself is still the placeholder address
 *    from early on — separate from the form, which now works properly
 *    once you set CONTACT_TO_EMAIL. Send me your real email and I will
 *    swap that link too.
 *
 * This script also runs "npm install resend" for you.
 */
const fs = require("fs");
const path = require("path");
const { execSync } = require("child_process");
const root = process.cwd();

function fail(msg) { console.error("✖ " + msg); process.exit(1); }
if (!fs.existsSync(path.join(root, "package.json"))) fail("Run this from your project root.");

function write(rel, content) {
  const full = path.join(root, rel);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, content, "utf8");
  console.log("✓ wrote " + rel);
}

write('app/achievements/page.js', 'import fs from "fs";\nimport path from "path";\nimport ClassesScripts from "@/components/ClassesScripts";\n\n// Same auto-discovery pattern as the homepage videos — drop a file into\n// public/videos/podcast/ and it plays automatically, muted and looped.\nfunction findPodcastVideo() {\n  const dir = path.join(process.cwd(), "public", "videos", "podcast");\n  const extToType = { ".mp4": "video/mp4", ".webm": "video/webm", ".mov": "video/quicktime" };\n  try {\n    if (!fs.existsSync(dir)) return null;\n    const match = fs.readdirSync(dir).find((f) => extToType[path.extname(f).toLowerCase()]);\n    if (!match) return null;\n    return { src: "/videos/podcast/" + match, type: extToType[path.extname(match).toLowerCase()] };\n  } catch {\n    return null;\n  }\n}\n\nexport const metadata = {\n  title: "Achievements: Gele Glamzzz | Recognition & Milestones",\n  description: "Styling Grammy-nominated artist Ayra Starr, a Vogue feature, and gele workshops hosted across London and leading UK universities.",\n  keywords: ["Ayra Starr gele", "gele Vogue feature", "gele university workshops UK", "notable gele stylist"],\n  alternates: { canonical: "/achievements" },\n};\n\nexport default function AchievementsPage() {\n  const podcastVideo = findPodcastVideo();\n  return (\n    <>\n      <section className="page-opener">\n        <div className="container container--narrow">\n          <span className="eyebrow" data-reveal>Recognition</span>\n          <h1 className="h2" data-reveal style={{ marginTop: ".8rem" }}>Where the work<br />has travelled.</h1>\n          <p className="lede page-opener__lede" data-reveal>A gele is made in one room and, sometimes, it goes on to travel a lot further than that room. A few of the moments Gele Glamzzz is proudest of.</p>\n        </div>\n      </section>\n\n      <section className="section-pad on-dark" style={{ background: "var(--void)", color: "var(--ivory)", paddingTop: "clamp(1rem,3vw,2rem)" }}>\n        <div className="container container--narrow">\n          <div className="achievements-list">\n\n            <div className="achievement">\n              <span className="achievement__num">01</span>\n              <div className="achievement__media media-frame" data-reveal-scale>\n                <div className="dissolve">\n                  <img src="/images/ayra-starr-stage.jpg" alt="Ayra Starr performing on stage wearing a coral headwrap styled by Gele Glamzzz" loading="lazy" />\n                  <img src="/images/final-cta-look.jpg" alt="Ayra Starr in a pink gele styled by Gele Glamzzz" loading="lazy" />\n                </div>\n              </div>\n              <div className="achievement__body" data-reveal>\n                <h3 className="h3">A global viral moment.</h3>\n                <p className="body-copy">Styling Ayra Starr, a Grammy-nominated global artist, in a Gele Glamzzz headwrap was never going to stay quiet. The look travelled across timelines and comment sections worldwide and helped turn gele styling into a viral moment among audiences who had never worn one before. It was styled here, by Gele Glamzzz.</p>\n                <div className="social-buzz">\n                  <div className="social-buzz__media"><img src="/images/ayra-starr-x-buzz.jpg" alt="Ayra Starr performing live in the coral headwrap, as shared on X" loading="lazy" /></div>\n                  <div className="social-buzz__body">\n                    <span className="social-buzz__source">As seen on X</span>\n                    <p className="social-buzz__quote">&ldquo;Ayra Starr ate this gele look&rdquo; 🔥</p>\n                    <span className="social-buzz__handle">@AlbumTalks</span>\n                  </div>\n                </div>\n              </div>\n            </div>\n\n            <div className="achievement">\n              <span className="achievement__num">02</span>\n              <div className="achievement__media media-frame" data-reveal-scale>\n                <div className="media-frame__art"><img src="/images/vogue-feature.jpg" alt="Runway model wearing a green and blue gele, Vogue-tagged fashion show feature" loading="lazy" style={{ objectPosition: "50% 8%" }} /></div>\n              </div>\n              <div className="achievement__body" data-reveal>\n                <h3 className="h3">Featured in Vogue.</h3>\n                <p className="body-copy">The craft behind the crown caught the attention of one of fashion&apos;s most recognised names. Gele Glamzzz has been featured in Vogue, sitting alongside some of the industry&apos;s most established houses.</p>\n              </div>\n            </div>\n\n            <div className="achievement">\n              <span className="achievement__num">03</span>\n              <div className="achievement__media media-frame" data-reveal-scale>\n                <div className="media-frame__art"><img src="/images/owner-teaching.jpg" alt="Gele tying workshop in progress" loading="lazy" /></div>\n              </div>\n              <div className="achievement__body" data-reveal>\n                <h3 className="h3">Teaching the next generation.</h3>\n                <p className="body-copy">Beyond individual bookings, Gele Glamzzz has taken the craft into some of the UK&apos;s leading university campuses, hosting hands-on workshops that introduce a new generation to the art of the gele, alongside a flagship workshop in the heart of London.</p>\n                <div className="achievement__venues">\n                  <span>London</span>\n                  <span>University of Leicester</span>\n                  <span>University of Kent</span>\n                  <span>University of Warwick</span>\n                </div>\n              </div>\n            </div>\n\n            <div className="achievement">\n              <span className="achievement__num">04</span>\n              <div className="achievement__media media-frame" data-reveal-scale>\n                <div className="media-frame__art">\n                  {podcastVideo ? (\n                    <video muted loop autoPlay playsInline preload="metadata" poster="/images/insta-podcast.jpg" aria-label="Gele Glamzzz founder on a podcast appearance">\n                      <source src={podcastVideo.src} type={podcastVideo.type} />\n                    </video>\n                  ) : (\n                    <img src="/images/insta-podcast.jpg" alt="Gele Glamzzz founder appearing on a podcast" loading="lazy" />\n                  )}\n                </div>\n              </div>\n              <div className="achievement__body" data-reveal>\n                <h3 className="h3">On the mic, off the runway.</h3>\n                <p className="body-copy">The craft doesn&apos;t only show up on stage and in front of the camera. Gele Glamzzz&apos;s founder sat down for a podcast conversation, talking through the story behind the brand, the culture behind the craft, and what it takes to turn a single fold into a career.</p>\n              </div>\n            </div>\n\n          </div>\n        </div>\n      </section>\n\n      <ClassesScripts />\n    </>\n  );\n}\n');
write('app/globals.css', '/* ==========================================================================\n   0. RESET\n   ========================================================================== */\n*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\nhtml { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }\nbody {\n  min-height: 100svh;\n  overflow-x: hidden;\n  background: var(--cream);\n  color: var(--void);\n  font-family: var(--font-sans);\n  font-size: 1.0625rem;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n}\nimg, svg, video { display: block; max-width: 100%; }\na { color: inherit; text-decoration: none; }\nbutton, input, textarea, select { font: inherit; color: inherit; }\nbutton { background: none; border: 0; cursor: pointer; }\nul, ol { list-style: none; }\nh1, h2, h3, h4 { font-weight: inherit; }\n\n/* ==========================================================================\n   1. DESIGN TOKENS\n   ========================================================================== */\n:root {\n  /* ---- colour: base ---- */\n  --void: #15100c;         /* rich, warm black */\n  --espresso: #2b2018;     /* deep espresso brown */\n  --champagne: #dac49c;    /* muted champagne */\n  --ivory: #f2e9d8;        /* warm ivory */\n  --cream: #faf6ee;        /* soft cream */\n\n  /* ---- colour: accents (used sparingly) ---- */\n  --gold: #b8874a;\n  --gold-soft: #d7ab6e;\n  --bronze: #8a6b45;\n  --burgundy: #5c2231;\n  --terracotta: #a6522e;\n\n  /* ---- semantic ---- */\n  --ink: var(--void);\n  --paper: var(--cream);\n  --line-dark: rgba(21,16,12,.14);\n  --line-light: rgba(242,233,216,.2);\n\n  /* ---- type ---- */\n  --font-serif: \'Fraunces\', \'Iowan Old Style\', serif;\n  --font-sans: \'Manrope\', -apple-system, BlinkMacSystemFont, sans-serif;\n\n  /* ---- fluid type scale ---- */\n  --fs-micro: 0.6875rem;\n  --fs-xs: 0.8125rem;\n  --fs-sm: 0.9375rem;\n  --fs-base: 1.0625rem;\n  --fs-md: clamp(1.25rem, 1.05rem + 0.7vw, 1.625rem);\n  --fs-lg: clamp(1.75rem, 1.3rem + 1.8vw, 2.75rem);\n  --fs-xl: clamp(2.5rem, 1.6rem + 3.6vw, 4.5rem);\n  --fs-xxl: clamp(3.2rem, 1.8rem + 5.8vw, 6.75rem);\n  --fs-display: clamp(3.6rem, 1.4rem + 9vw, 9.5rem);\n\n  /* ---- spacing ---- */\n  --gutter: clamp(1.25rem, 3vw, 3rem);\n  --section-y: clamp(5rem, 4rem + 6vw, 10rem);\n\n  /* ---- motion ---- */\n  --ease: cubic-bezier(.22,1,.36,1);\n  --ease-soft: cubic-bezier(.4,0,.2,1);\n  --dur-fast: .3s;\n  --dur-med: .6s;\n  --dur-slow: 1.1s;\n\n  --nav-h: 84px;\n}\n@media (max-width: 640px) { :root { --nav-h: 68px; } }\n\n@media (prefers-reduced-motion: reduce) {\n  html { scroll-behavior: auto; }\n  *, *::before, *::after {\n    animation-duration: 0.001ms !important;\n    animation-iteration-count: 1 !important;\n    transition-duration: 0.001ms !important;\n    scroll-behavior: auto !important;\n  }\n}\n\n/* ==========================================================================\n   2. LAYOUT + TYPE UTILITIES\n   ========================================================================== */\n.container { width: 100%; max-width: 1600px; margin-inline: auto; padding-inline: var(--gutter); }\n.container--narrow { max-width: 1100px; }\n.container--text { max-width: 640px; }\n\nsection { position: relative; }\n.section-pad { padding-block: var(--section-y); }\n\n.visually-hidden {\n  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;\n  overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0;\n}\n\n.skip-link {\n  position: fixed; top: -100%; left: 1rem; z-index: 999;\n  background: var(--void); color: var(--ivory); padding: .9rem 1.4rem;\n  font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .08em;\n  transition: top .25s var(--ease);\n}\n.skip-link:focus { top: 1rem; }\n\n.eyebrow {\n  font-family: var(--font-sans); font-weight: 600; font-size: var(--fs-xs);\n  letter-spacing: .18em; text-transform: uppercase; color: var(--gold);\n}\n\n.display-1, .display-2 {\n  font-family: var(--font-serif); font-weight: 500; letter-spacing: -0.01em;\n  line-height: .96; text-wrap: balance;\n}\n.display-1 { font-size: var(--fs-display); }\n.display-2 { font-size: var(--fs-xxl); }\n\n.h2 { font-family: var(--font-serif); font-weight: 500; font-size: var(--fs-xl); line-height: 1.04; letter-spacing: -0.01em; }\n.h3 { font-family: var(--font-serif); font-weight: 500; font-size: var(--fs-lg); line-height: 1.08; }\n\n.accent-dot { color: var(--gold); }\n\n.lede {\n  font-family: var(--font-sans); font-weight: 500; font-size: var(--fs-md);\n  line-height: 1.5; color: var(--espresso);\n}\n\n.body-copy {\n  font-family: var(--font-sans); font-size: var(--fs-base); line-height: 1.75;\n  color: rgba(21,16,12,.78); max-width: 58ch;\n}\n.on-dark .body-copy, .on-dark .lede { color: rgba(242,233,216,.82); }\n\n.pull-quote {\n  font-family: var(--font-serif); font-style: italic; font-weight: 400;\n  font-size: var(--fs-lg); line-height: 1.4; letter-spacing: -0.005em;\n}\n\n.label-line {\n  display: inline-flex; align-items: center; gap: .6em;\n  font-family: var(--font-sans); font-size: var(--fs-xs); font-weight: 600;\n  letter-spacing: .14em; text-transform: uppercase;\n}\n.label-line::before { content: \'\'; width: 22px; height: 1px; background: currentColor; opacity: .5; }\n\n/* ---- buttons ---- */\n.btn {\n  position: relative; display: inline-flex; align-items: center; gap: .6rem;\n  font-family: var(--font-sans); font-weight: 600; font-size: var(--fs-xs);\n  letter-spacing: .14em; text-transform: uppercase; white-space: nowrap;\n  padding: 1.15rem 1.9rem; border: 1px solid currentColor; overflow: hidden;\n  transition: background var(--dur-fast) var(--ease-soft), color var(--dur-fast) var(--ease-soft), transform .25s var(--ease-soft);\n  transform: translate(var(--magnet-x, 0px), var(--magnet-y, 0px));\n}\n.btn::before {\n  content: ""; position: absolute; inset: -20% -60%; z-index: 0; pointer-events: none;\n  background: linear-gradient(115deg, transparent 42%, rgba(215,171,110,.55) 50%, transparent 58%);\n  transform: translateX(-100%); transition: transform .75s cubic-bezier(.22,1,.36,1);\n}\n.btn:hover::before { transform: translateX(45%); }\n.btn__arrow { display: inline-block; transition: transform var(--dur-fast) var(--ease-soft); }\n.btn:hover .btn__arrow { transform: translateX(5px); }\n.btn:active { transform: translate(var(--magnet-x, 0px), var(--magnet-y, 0px)) scale(.97); }\n\n.btn--primary { background: var(--void); color: var(--ivory); border-color: var(--void); }\n.btn--primary:hover { background: var(--terracotta); border-color: var(--terracotta); color: var(--cream); }\n\n.btn--ghost { background: transparent; color: var(--void); border-color: currentColor; }\n.btn--ghost:hover { background: var(--void); color: var(--ivory); }\n\n.on-dark .btn--ghost { color: var(--ivory); }\n.on-dark .btn--ghost:hover { background: var(--ivory); color: var(--void); }\n.on-dark .btn--primary { background: var(--gold); border-color: var(--gold); color: var(--void); }\n.on-dark .btn--primary:hover { background: var(--ivory); border-color: var(--ivory); }\n\n.text-link {\n  position: relative; font-family: var(--font-sans); font-weight: 600;\n  font-size: var(--fs-xs); letter-spacing: .1em; text-transform: uppercase;\n  padding-bottom: .3em;\n}\n.text-link::after {\n  content: \'\'; position: absolute; left: 0; right: 100%; bottom: 0; height: 1px;\n  background: currentColor; transition: right var(--dur-med) var(--ease);\n}\n.text-link:hover::after { right: 0; }\n\n/* ---- media-frame: bespoke placeholder-photography system ---- */\n.media-frame {\n  position: relative; overflow: hidden; background: var(--espresso);\n  isolation: isolate;\n}\n.media-frame img { width: 100%; height: 100%; object-fit: cover; }\n.media-frame__art { position: absolute; inset: 0; width: 100%; height: 100%; }\n.media-frame__art img, .media-frame__art video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; display: block; }\n.media-frame__art svg { width: 100%; height: 100%; }\n.grain-overlay {\n  position: fixed; inset: 0; z-index: 6; opacity: .1; mix-blend-mode: overlay;\n  pointer-events: none;\n}\n.media-frame__tag {\n  position: absolute; left: 0; right: 0; bottom: 0; z-index: 2;\n  display: flex; align-items: center; gap: .5em;\n  padding: .8em 1em; font-family: var(--font-sans); font-size: 9.5px;\n  font-weight: 700; letter-spacing: .12em; text-transform: uppercase;\n  color: rgba(242,233,216,.72); background: linear-gradient(0deg, rgba(0,0,0,.45), transparent);\n}\n.media-frame__tag::before { content: \'◇\'; color: var(--gold); font-size: 10px; }\n\n/* ---- pictures move by themselves: a slow, continuous ambient zoom on every frame ---- */\n@keyframes ambientZoom { from { transform: scale(1); } to { transform: scale(1.09); } }\n.has-motion .media-frame__art { animation: ambientZoom 20s ease-in-out infinite alternate; }\n.gallery__item:nth-child(2n) .media-frame__art { animation-delay: -4s; }\n.gallery__item:nth-child(3n) .media-frame__art { animation-delay: -11s; }\n.instagram__item:nth-child(2n) .media-frame__art { animation-delay: -3s; }\n.instagram__item:nth-child(3n) .media-frame__art { animation-delay: -8s; }\n.journal__item:nth-child(2n) .media-frame__art { animation-delay: -6s; }\n\n/* ---- the "water" effect: reserved for a handful of large, hero-scale frames ---- */\n.has-motion .media-frame--ripple .media-frame__art { filter: url(#waterRipple); }\n@media (prefers-reduced-motion: reduce) { .media-frame--ripple .media-frame__art { filter: none; } }\n\n/* ==========================================================================\n   3. CUSTOM CURSOR (desktop / fine-pointer only — see JS gate)\n   ========================================================================== */\n.cursor {\n  position: fixed; top: 0; left: 0; z-index: 900; pointer-events: none;\n  width: 14px; height: 14px; border-radius: 50%; background: var(--ivory);\n  mix-blend-mode: difference; transform: translate(-50%,-50%);\n  display: flex; align-items: center; justify-content: center;\n  transition: width var(--dur-fast) var(--ease-soft), height var(--dur-fast) var(--ease-soft),\n              background var(--dur-fast) var(--ease-soft);\n  will-change: transform;\n}\n.cursor__label {\n  font-family: var(--font-sans); font-weight: 700; font-size: 10px;\n  letter-spacing: .12em; text-transform: uppercase; color: var(--void);\n  opacity: 0; transition: opacity var(--dur-fast) var(--ease-soft);\n  mix-blend-mode: normal;\n}\n.cursor.is-view, .cursor.is-book { width: 74px; height: 74px; background: var(--ivory); }\n.cursor.is-view .cursor__label, .cursor.is-book .cursor__label { opacity: 1; }\n.cursor.is-link { width: 30px; height: 30px; background: transparent; border: 1px solid var(--ivory); }\n.cursor.is-hidden { opacity: 0; }\nhtml.has-fine-pointer.has-motion body { cursor: none; }\nhtml.has-fine-pointer.has-motion a, html.has-fine-pointer.has-motion button { cursor: none; }\n\n/* ==========================================================================\n   4. LOADING SCREEN\n   ========================================================================== */\n.loader {\n  position: fixed; inset: 0; z-index: 1000;\n  display: flex; align-items: center; justify-content: center; flex-direction: column;\n  gap: 1.6rem;\n}\n.loader__mark {\n  font-family: var(--font-serif); font-size: clamp(1.6rem, 6vw, 2.6rem);\n  letter-spacing: .05em; color: var(--ivory); display: flex; overflow: hidden;\n}\n.loader__mark span { display: inline-block; transform: translateY(110%); }\n.loader__bar { width: min(220px, 40vw); height: 1px; background: var(--line-light); position: relative; overflow: hidden; }\n.loader__bar span { position: absolute; inset: 0; background: var(--gold); transform: scaleX(0); transform-origin: left; }\n.loader.is-done { pointer-events: none; }\n\n/* pure CSS sequence — no external library to wait for, so it plays\n   identically regardless of connection speed. Letters rise, bar fills,\n   mark+bar dissolve, then the shutter bars part to reveal the site. */\n@keyframes loaderLetterUp { to { transform: translateY(0%); } }\n@keyframes loaderBarFill { to { transform: scaleX(1); } }\n@keyframes loaderDissolve { to { opacity: 0; transform: scale(1.06); filter: blur(6px); } }\n\n.has-motion .loader__mark span {\n  animation-name: loaderLetterUp; animation-duration: .6s;\n  animation-timing-function: cubic-bezier(.16,1,.3,1); animation-fill-mode: forwards;\n}\n.has-motion .loader__bar span { animation: loaderBarFill .5s ease-in-out .75s forwards; }\n.has-motion .loader__mark, .has-motion .loader__bar { animation: loaderDissolve .45s ease-in 1.35s forwards; }\n\n/* ==========================================================================\n   5. NAVIGATION\n   ========================================================================== */\n.nav {\n  position: fixed; top: 0; left: 0; right: 0; z-index: 400; height: var(--nav-h);\n  display: flex; align-items: center; transition: background var(--dur-med) var(--ease-soft), border-color var(--dur-med) var(--ease-soft);\n  border-bottom: 1px solid transparent;\n}\n.nav__inner { width: 100%; display: flex; align-items: center; justify-content: space-between; }\n.nav.is-scrolled { background: rgba(250,246,238,.9); backdrop-filter: blur(10px); border-color: var(--line-dark); }\n.nav.is-scrolled .nav__link, .nav.is-scrolled .nav__logo { color: var(--void); }\n.nav.is-open-on-dark .nav__link, .nav.is-open-on-dark .nav__logo { color: var(--void); }\n\n.nav__logo {\n  display: inline-flex; align-items: center; gap: .5em;\n  font-family: var(--font-serif); font-size: var(--fs-sm); letter-spacing: .16em;\n  color: var(--ivory); transition: color var(--dur-fast) var(--ease-soft);\n}\n.nav__logo-mark { width: 1.5em; height: 1.5em; color: var(--gold); flex-shrink: 0; }\n.nav__links { display: none; align-items: center; gap: 2.4rem; }\n.nav__link {\n  position: relative; font-family: var(--font-sans); font-size: var(--fs-xs);\n  font-weight: 600; letter-spacing: .12em; text-transform: uppercase;\n  color: var(--ivory); padding: .3rem 0; transition: color var(--dur-fast) var(--ease-soft);\n}\n.nav__link.is-current::after { right: 0; }\n.nav__link::after {\n  content: \'\'; position: absolute; left: 0; right: 100%; bottom: 0; height: 1px;\n  background: var(--gold); transition: right var(--dur-med) var(--ease);\n}\n.nav__link:hover::after { right: 0; }\n.nav__book {\n  border: 1px solid currentColor; padding: .7rem 1.3rem;\n}\n.nav__book::after { display: none; }\n.nav__book:hover { background: var(--gold); border-color: var(--gold); color: var(--void); }\n\n.nav__burger {\n  display: flex; flex-direction: column; justify-content: center; gap: 6px;\n  width: 34px; height: 34px; z-index: 410;\n}\n.nav__burger span {\n  display: block; height: 1px; width: 100%; background: var(--ivory);\n  transition: transform var(--dur-fast) var(--ease-soft), opacity var(--dur-fast) var(--ease-soft), background var(--dur-fast);\n}\n.nav.is-scrolled .nav__burger span { background: var(--void); }\n.nav__burger.is-active span { background: var(--ivory) !important; }\n.nav__burger.is-active span:nth-child(1) { transform: translateY(3.5px) rotate(45deg); }\n.nav__burger.is-active span:nth-child(2) { opacity: 0; }\n.nav__burger.is-active span:nth-child(3) { transform: translateY(-3.5px) rotate(-45deg); }\n\n@media (min-width: 900px) {\n  .nav__links { display: flex; }\n  .nav__burger { display: none; }\n}\n\n/* single-file "views" — one document, one visible view at a time */\n.view { display: none; }\n.view.is-active { display: block; }\n/* the hero sits full-bleed behind the transparent nav by design; every other\n   view\'s first section needs to clear the fixed nav explicitly */\n.view:not([data-view="home"]) > *:first-child { margin-top: var(--nav-h); }\n\n.page-transition { position: fixed; inset: 0; z-index: 9000; display: flex; pointer-events: none; }\n.page-transition span {\n  flex: 1 1 0; background: var(--void); transform: scaleY(0); transform-origin: bottom;\n  transition: transform .28s cubic-bezier(.65,0,.35,1);\n}\n.page-transition span + span { border-left: 1px solid rgba(0,0,0,.2); }\n.page-transition.is-active { pointer-events: auto; }\n.page-transition.is-closing span { transform: scaleY(1); }\n.page-transition span:nth-child(2) { transition-delay: .03s; }\n.page-transition span:nth-child(3) { transition-delay: .06s; }\n.page-transition span:nth-child(4) { transition-delay: .09s; }\n.page-transition span:nth-child(5) { transition-delay: .12s; }\n.page-transition span:nth-child(6) { transition-delay: .15s; }\n\n/* ---- mobile full-screen menu ---- */\n.mobile-menu {\n  position: fixed; inset: 0; z-index: 405; background: var(--void);\n  clip-path: circle(2% at calc(100% - 34px) 40px); pointer-events: none;\n  transition: clip-path .75s var(--ease), visibility 0s linear .75s; visibility: hidden;\n  display: flex; flex-direction: column; justify-content: center;\n  padding: var(--gutter);\n}\n.mobile-menu.is-open { clip-path: circle(150% at calc(100% - 34px) 40px); pointer-events: auto; visibility: visible; transition: clip-path .75s var(--ease); }\n.mobile-menu__links { display: flex; flex-direction: column; gap: .3rem; }\n.mobile-menu__link {\n  font-family: var(--font-serif); font-size: clamp(2.2rem, 11vw, 3.2rem);\n  color: var(--ivory); padding: .3rem 0; border-bottom: 1px solid var(--line-light);\n  opacity: 0; transform: translateY(24px);\n  transition: opacity .5s var(--ease), transform .5s var(--ease);\n}\n.mobile-menu.is-open .mobile-menu__link { opacity: 1; transform: none; }\n.mobile-menu__link:nth-child(1) { transition-delay: .05s; }\n.mobile-menu__link:nth-child(2) { transition-delay: .1s; }\n.mobile-menu__link:nth-child(3) { transition-delay: .15s; }\n.mobile-menu__link:nth-child(4) { transition-delay: .2s; }\n.mobile-menu__link:nth-child(5) { transition-delay: .25s; }\n.mobile-menu__link:nth-child(6) { transition-delay: .3s; }\n.mobile-menu__foot {\n  margin-top: 2.4rem; display: flex; gap: 1.6rem;\n  font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .1em;\n  text-transform: uppercase; color: rgba(242,233,216,.65);\n  opacity: 0; transition: opacity .6s var(--ease) .35s;\n}\n.mobile-menu.is-open .mobile-menu__foot { opacity: 1; }\n@media (min-width: 900px) { .mobile-menu { display: none; } }\n\n/* ==========================================================================\n   6. HERO\n   ========================================================================== */\n.hero {\n  position: relative; height: 100svh; min-height: 560px; background: var(--void); color: var(--ivory);\n  display: flex; align-items: flex-end; overflow: hidden;\n}\n\n/* ---- full-bleed background: image now, <video> the instant a source is added ---- */\n.hero__media { position: absolute; inset: 0; width: 100%; height: 100%; background: var(--espresso); overflow: hidden; }\n.hero__media .media-frame__art {\n  position: absolute; inset: -4%; width: 108%; height: 108%; transform: scale(1.1);\n}\n.has-motion .hero__media .media-frame__art { animation: heroKenBurns 24s ease-in-out infinite alternate; }\n@keyframes heroKenBurns { from { transform: scale(1.1) translate(0,0); } to { transform: scale(1.18) translate(-1.4%,-1.8%); } }\n\n.hero__video {\n  position: absolute; inset: 0; z-index: 1; width: 100%; height: 100%; object-fit: cover;\n  opacity: 0; transition: opacity 1.6s var(--ease-soft);\n}\n.hero__video.is-ready { opacity: 1; }\n\n.hero__scrim {\n  position: absolute; inset: 0; z-index: 2;\n  background:\n    linear-gradient(0deg, rgba(13,10,7,.96) 0%, rgba(13,10,7,.62) 34%, rgba(13,10,7,.16) 58%, rgba(13,10,7,.4) 100%),\n    linear-gradient(100deg, rgba(13,10,7,.55) 0%, rgba(13,10,7,0) 42%);\n}\n\n/* ---- the "shutter" — a magazine-cover style reveal, plays once on load ---- */\n.hero__shutter { position: absolute; inset: 0; z-index: 40; display: flex; pointer-events: none; }\n.hero__shutter span { flex: 1 1 0; background: var(--void); transform-origin: bottom; }\n.hero__shutter span + span { border-left: 1px solid rgba(0,0,0,.2); }\n\n/* ---- editorial framing: coverline + registration marks ---- */\n.hero__marks { position: absolute; inset: clamp(1rem,2.6vw,1.8rem); z-index: 5; pointer-events: none; }\n.hero__marks i { position: absolute; width: 15px; height: 15px; opacity: 0; border-color: var(--gold-soft); border-style: solid; }\n.has-motion .hero__marks i { transition: opacity .6s var(--ease-soft) 1.3s; }\n.hero__marks.is-in i { opacity: .7; }\n.hero__marks i:nth-child(1) { top: 0; left: 0; border-width: 1px 0 0 1px; }\n.hero__marks i:nth-child(2) { top: 0; right: 0; border-width: 1px 1px 0 0; }\n.hero__marks i:nth-child(3) { bottom: 0; left: 0; border-width: 0 0 1px 1px; }\n.hero__marks i:nth-child(4) { bottom: 0; right: 0; border-width: 0 1px 1px 0; }\n\n.hero__issue {\n  position: absolute; z-index: 5; top: calc(var(--nav-h) + clamp(1rem,3vw,1.8rem)); right: var(--gutter);\n  text-align: right; color: rgba(242,233,216,.75); opacity: 0; transform: translateY(-8px);\n}\n.has-motion .hero__issue { transition: opacity .8s var(--ease-soft) 1.1s, transform .8s var(--ease-soft) 1.1s; }\n.hero__issue.is-in { opacity: 1; transform: none; }\n.hero__issue span { display: block; font-family: var(--font-sans); font-size: 10.5px; letter-spacing: .16em; text-transform: uppercase; }\n.hero__issue span:first-child { color: var(--gold-soft); margin-bottom: .3em; }\n\n.hero__content {\n  position: relative; z-index: 4; width: 100%;\n  padding-inline: var(--gutter); padding-bottom: clamp(3rem, 6vw, 5.5rem);\n  display: grid; gap: clamp(1.6rem, 3vw, 2.4rem);\n}\n\n.hero__headline {\n  font-family: var(--font-serif); font-weight: 500; letter-spacing: -0.01em;\n}\n.hero__headline .line {\n  display: block; overflow: hidden; line-height: 1;\n}\n.hero__headline .line span { display: block; transform: translateY(105%); }\n.hero__headline .line--sm { font-size: clamp(1.3rem, 0.9rem + 1.6vmin, 2.2rem); opacity: .82; }\n.hero__headline .line--lg { font-size: clamp(2.6rem, 1rem + 7vmin, 7rem); }\n\n.hero__foot {\n  display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between;\n  gap: 2rem; max-width: 1500px;\n}\n.hero__sub { max-width: 34ch; font-family: var(--font-sans); font-size: var(--fs-md); color: rgba(242,233,216,.82); }\n.hero__ctas { display: flex; flex-wrap: wrap; gap: 1rem; }\n\n.hero__scroll {\n  position: absolute; left: var(--gutter); bottom: clamp(1.2rem,3vw,2rem); z-index: 2;\n  display: none; align-items: center; gap: .7rem; color: rgba(242,233,216,.6);\n  font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .16em; text-transform: uppercase;\n}\n.hero__scroll-line { width: 1px; height: 34px; background: rgba(242,233,216,.35); overflow: hidden; }\n.hero__scroll-line span { display: block; width: 100%; height: 40%; background: var(--gold); transform: translateY(-100%); animation: scrollcue 2.2s ease-in-out infinite; }\n@keyframes scrollcue { 0% { transform: translateY(-100%);} 60%,100% { transform: translateY(220%);} }\n@media (min-width: 700px) { .hero__scroll { display: flex; } }\n@media (prefers-reduced-motion: reduce) { .hero__scroll-line span { animation: none; transform: translateY(0); } }\n\n/* progress bar for whole-page scroll */\n.scroll-progress {\n  position: fixed; top: 0; left: 0; height: 2px; background: var(--gold); z-index: 500;\n  width: 0%; transition: width .1s linear;\n}\n\n/* ==========================================================================\n   7. INTRO / PHILOSOPHY\n   ========================================================================== */\n.intro { background: var(--cream); overflow: hidden; }\n.intro__grid {\n  display: grid; gap: clamp(2.5rem, 5vw, 5rem); align-items: center;\n  grid-template-columns: 1fr;\n}\n.intro__media { aspect-ratio: 4/5; }\n.intro__text .h2 { margin-bottom: 1.6rem; }\n.intro__rule { width: 64px; height: 1px; background: var(--gold); margin-bottom: 1.6rem; }\n@media (min-width: 900px) {\n  .intro__grid { grid-template-columns: .9fr 1.1fr; }\n  .intro--media-right .intro__media { order: 2; }\n}\n\n/* ==========================================================================\n   8. BRAND STORY\n   ========================================================================== */\n.story { background: var(--espresso); color: var(--ivory); }\n.story__head { max-width: 720px; margin-bottom: clamp(3rem, 6vw, 5.5rem); }\n.story__grid { display: grid; gap: clamp(3rem, 6vw, 6rem); }\n.story__block { display: grid; gap: clamp(2rem, 4vw, 3.5rem); align-items: start; grid-template-columns: 1fr; }\n.story__block:nth-child(even) .story__media { order: -1; }\n.story__media { aspect-ratio: 3/4; }\n.story__quote { border-left: 1px solid var(--gold); padding-left: 1.6rem; }\n.story__quote cite { display: block; margin-top: 1.2rem; font-style: normal; }\n@media (min-width: 900px) {\n  .story__block { grid-template-columns: 1fr 1fr; }\n  .story__block:nth-child(even) .story__media { order: 2; }\n  .story__media { aspect-ratio: 4/5; }\n}\n\n/* ==========================================================================\n   9. ARTISTRY GALLERY (editorial, asymmetric)\n   ========================================================================== */\n.gallery { background: var(--cream); }\n.gallery__head {\n  display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-end;\n  gap: 1.5rem; margin-bottom: clamp(2.5rem, 5vw, 4rem);\n}\n.gallery__grid {\n  display: grid; grid-template-columns: repeat(6, 1fr);\n  grid-auto-rows: 13vw; gap: clamp(.6rem, 1.4vw, 1.4rem);\n}\n@media (max-width: 720px) { .gallery__grid { grid-auto-rows: 46vw; grid-template-columns: repeat(2,1fr); } }\n\n.gallery__item {\n  transition: transform .25s var(--ease-soft);\n  transform-style: preserve-3d; will-change: transform;\n  position: relative; overflow: hidden; cursor: pointer;\n  grid-column: span 2; grid-row: span 2;\n}\n.gallery__item img, .gallery__item .media-frame { width: 100%; height: 100%; }\n.gallery__item .media-frame__art { transition: filter .8s var(--ease); }\n.gallery__item:hover .media-frame__art { filter: brightness(1.08); }\n\n.gallery__item--a { grid-column: span 2; grid-row: span 3; }\n.gallery__item--b { grid-column: span 3; grid-row: span 2; }\n.gallery__item--c { grid-column: span 2; grid-row: span 2; }\n.gallery__item--d { grid-column: span 3; grid-row: span 3; }\n.gallery__item--e { grid-column: span 2; grid-row: span 2; }\n.gallery__item--f { grid-column: span 2; grid-row: span 3; }\n.gallery__item--g { grid-column: span 4; grid-row: span 2; }\n.gallery__item--h { grid-column: span 2; grid-row: span 2; }\n@media (max-width: 720px) {\n  .gallery__item, .gallery__item--a, .gallery__item--b, .gallery__item--c,\n  .gallery__item--d, .gallery__item--e, .gallery__item--f, .gallery__item--g, .gallery__item--h {\n    grid-column: span 1; grid-row: span 2;\n  }\n  .gallery__item--d, .gallery__item--g { grid-column: span 2; }\n}\n\n.gallery__caption {\n  position: absolute; left: 0; bottom: 0; right: 0; z-index: 2; padding: 1.1rem 1.2rem;\n  transform: translateY(100%); transition: transform var(--dur-med) var(--ease);\n  background: linear-gradient(0deg, rgba(0,0,0,.55), transparent);\n}\n.gallery__item:hover .gallery__caption, .gallery__item:focus-visible .gallery__caption { transform: translateY(0); }\n.gallery__caption p { font-family: var(--font-sans); font-size: 10.5px; letter-spacing: .12em; text-transform: uppercase; color: var(--ivory); line-height: 1.6; }\n.gallery__caption p:first-child { color: var(--gold-soft); font-weight: 700; }\n\n/* ---- lightbox ---- */\n.lightbox {\n  position: fixed; inset: 0; z-index: 800; background: rgba(21,16,12,.96);\n  display: flex; align-items: center; justify-content: center; padding: 4vh var(--gutter);\n  opacity: 0; visibility: hidden; transition: opacity var(--dur-med) var(--ease-soft);\n}\n.lightbox.is-open { opacity: 1; visibility: visible; }\n.lightbox__frame { width: min(78vh, 100%); aspect-ratio: 4/5; max-height: 84vh; position: relative; }\n.lightbox__close, .lightbox__prev, .lightbox__next {\n  position: absolute; color: var(--ivory); font-family: var(--font-sans); font-size: var(--fs-xs);\n  letter-spacing: .12em; text-transform: uppercase; display: flex; align-items: center; gap: .5rem;\n}\n.lightbox__close { top: -3rem; right: 0; }\n.lightbox__prev { top: 50%; left: -3.6rem; transform: translateY(-50%); }\n.lightbox__next { top: 50%; right: -3.6rem; transform: translateY(-50%); }\n@media (max-width: 720px) {\n  .lightbox__prev { left: 0; top: auto; bottom: -3rem; transform: none; }\n  .lightbox__next { right: 0; top: auto; bottom: -3rem; transform: none; }\n}\n.lightbox__meta { position: absolute; left: 0; bottom: -2.6rem; color: rgba(242,233,216,.7); font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .08em; }\n\n/* ==========================================================================\n   10. FEATURED WORK (signature styles — hover to reveal)\n   ========================================================================== */\n.featured { background: var(--cream); }\n.featured__layout { display: grid; gap: clamp(2rem,4vw,3rem); grid-template-columns: 1fr; }\n.featured__media { aspect-ratio: 4/5; position: sticky; top: calc(var(--nav-h) + 2rem); }\n.featured__media .media-frame { width: 100%; height: 100%; }\n.featured__media .media-frame__art { opacity: 0; transition: opacity .6s var(--ease-soft); position: absolute; inset: 0; }\n.featured__media .media-frame__art.is-active { opacity: 1; }\n\n.featured__list { border-top: 1px solid var(--line-dark); }\n.featured__item {\n  display: flex; align-items: baseline; gap: clamp(1rem,3vw,2.4rem);\n  padding: clamp(1.2rem,3vw,2rem) 0; border-bottom: 1px solid var(--line-dark);\n  cursor: pointer;\n}\n.featured__num { font-family: var(--font-sans); font-size: var(--fs-xs); color: var(--gold); letter-spacing: .1em; }\n.featured__title { min-width: 0; font-family: var(--font-serif); font-size: clamp(1.4rem,5.5vw,2.8rem); line-height: 1.05; transition: color var(--dur-fast); flex: 1; }\n.featured__desc { display: none; max-width: 30ch; font-family: var(--font-sans); font-size: var(--fs-sm); color: rgba(21,16,12,.6); }\n.featured__item.is-active .featured__title { color: var(--terracotta); }\n@media (min-width: 700px) {\n  .featured__desc { display: block; }\n  .featured__layout { grid-template-columns: .95fr 1.05fr; }\n}\n\n/* ==========================================================================\n   11. SERVICES — "THE EXPERIENCE" (editorial interactive list)\n   ========================================================================== */\n.services { background: var(--void); color: var(--ivory); overflow: clip; }\n.services__row {\n  position: relative; display: flex; align-items: center; justify-content: space-between;\n  gap: 1rem; padding: clamp(1.4rem,3vw,2.2rem) 0; border-top: 1px solid var(--line-light);\n}\n.services__list > .services__row:last-child { border-bottom: 1px solid var(--line-light); }\n.services__title-wrap { display: flex; align-items: baseline; gap: .8rem; flex: 1 1 auto; min-width: 0; }\n.services__tag { flex-shrink: 0; font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .12em; color: var(--gold); }\n.services__title { min-width: 0; font-family: var(--font-serif); font-weight: 500; font-size: clamp(1.35rem,6.5vw,3.2rem); line-height: 1.05; transition: transform var(--dur-med) var(--ease); }\n.services__row:hover .services__title, .services__row:focus-within .services__title { transform: translateX(14px); color: var(--gold-soft); }\n.services__desc { display: none; max-width: 26ch; font-size: var(--fs-sm); color: rgba(242,233,216,.55); }\n.services__arrow { flex-shrink: 0; font-family: var(--font-serif); font-size: 1.4rem; transition: transform var(--dur-med) var(--ease); }\n.services__row:hover .services__arrow { transform: translateX(8px) rotate(0deg); }\n@media (min-width: 760px) { .services__desc { display: block; } }\n\n.services__preview {\n  position: fixed; top: 50%; left: 50%; width: min(30vw, 360px); aspect-ratio: 3/4;\n  transform: translate(-50%,-50%) scale(.92); pointer-events: none; z-index: 60;\n  opacity: 0; transition: opacity .35s var(--ease-soft), transform .5s var(--ease-soft);\n}\n.services__preview.is-visible { opacity: 1; transform: translate(-50%,-50%) scale(1); }\n@media (max-width: 900px) { .services__preview { display: none; } }\n\n/* mobile accordion */\n.services__accordion-body { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .45s var(--ease); }\n.services__accordion-body > div { overflow: hidden; }\n.services__row.is-open .services__accordion-body { grid-template-rows: 1fr; }\n.services__row.is-open .services__arrow { transform: rotate(90deg); }\n.services__accordion-media { margin-top: 1rem; aspect-ratio: 16/10; }\n\n/* ==========================================================================\n   12. PROCESS — "THE GELE GLAMZZZ EXPERIENCE"\n   ========================================================================== */\n.process { background: var(--ivory); }\n.process__grid { display: grid; grid-template-columns: 1fr; }\n.process__step {\n  display: grid; gap: 1rem; padding-block: clamp(2.5rem, 5vw, 4.5rem);\n  border-top: 1px solid var(--line-dark);\n}\n.process__grid > .process__step:last-child { border-bottom: 1px solid var(--line-dark); }\n.process__num {\n  font-family: var(--font-serif); font-size: clamp(3.5rem, 9vw, 7.5rem); line-height: .8;\n  color: transparent; -webkit-text-stroke: 1px var(--espresso); font-weight: 400;\n}\n.process__body { max-width: 46ch; }\n.process__body h3 { margin-bottom: .5rem; }\n@media (min-width: 860px) {\n  .process__step { grid-template-columns: 220px 1fr; align-items: center; }\n}\n\n/* ==========================================================================\n   13. BOOKING MODAL — luxury concierge wizard\n   ========================================================================== */\n.booking {\n  position: fixed; inset: 0; z-index: 700; background: var(--cream);\n  clip-path: circle(2% at 100% 0%); pointer-events: none;\n  transition: clip-path .85s var(--ease), visibility 0s linear .85s; visibility: hidden;\n  overflow-y: auto; -webkit-overflow-scrolling: touch;\n}\n.booking.is-open { clip-path: circle(150% at 100% 0%); pointer-events: auto; visibility: visible; transition: clip-path .85s var(--ease); }\n.booking__inner { min-height: 100%; display: flex; flex-direction: column; }\n\n.booking__head {\n  position: sticky; top: 0; z-index: 5; background: var(--cream);\n  display: flex; align-items: center; justify-content: space-between;\n  padding: 1.4rem var(--gutter); border-bottom: 1px solid var(--line-dark);\n}\n.booking__brand { font-family: var(--font-serif); font-size: var(--fs-sm); letter-spacing: .1em; }\n.booking__close { display: flex; align-items: center; gap: .6rem; font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .1em; text-transform: uppercase; }\n.booking__close-x { font-size: 1.3rem; line-height: 1; }\n\n.booking-page { background: var(--cream); }\n.booking-page__sticky { position: sticky; top: var(--nav-h); z-index: 30; background: var(--cream); padding-block: 1rem .9rem; border-bottom: 1px solid var(--line-dark); }\n.booking__progress { display: flex; gap: .4rem; padding: 0 var(--gutter); margin-top: 1.1rem; }\n.booking__progress-seg { flex: 1; height: 2px; background: var(--line-dark); position: relative; overflow: hidden; }\n.booking__progress-seg span { position: absolute; inset: 0; background: var(--terracotta); transform: scaleX(0); transform-origin: left; transition: transform .5s var(--ease); }\n.booking__progress-seg.is-done span, .booking__progress-seg.is-active span { transform: scaleX(1); }\n.booking__step-label { display: flex; justify-content: space-between; padding: .7rem var(--gutter) 0; font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .1em; text-transform: uppercase; color: rgba(21,16,12,.5); }\n\n.booking__body { flex: 1; padding: clamp(2rem,5vw,4rem) var(--gutter) 3rem; max-width: 980px; margin-inline: auto; width: 100%; }\n.booking__step { display: none; }\n.booking__step.is-active { display: block; animation: bstep-in .55s var(--ease); }\n@keyframes bstep-in { from { opacity: 0; transform: translateY(18px);} to { opacity:1; transform: translateY(0);} }\n@media (prefers-reduced-motion: reduce) { .booking__step.is-active { animation: none; } }\n\n.booking__kicker { margin-bottom: .8rem; }\n.booking__title { margin-bottom: clamp(1.6rem,4vw,3rem); max-width: 20ch; }\n\n/* step 1 — category cards */\n.option-grid { display: grid; grid-template-columns: repeat(auto-fit,minmax(220px,1fr)); gap: 1rem; }\n.option-card {\n  border: 1px solid var(--line-dark); padding: 1.6rem 1.4rem; text-align: left;\n  display: flex; flex-direction: column; gap: 2.2rem; min-height: 128px;\n  transition: border-color var(--dur-fast), background var(--dur-fast);\n}\n.option-card:hover { border-color: var(--espresso); }\n.option-card.is-selected { background: var(--void); border-color: var(--void); color: var(--ivory); }\n.option-card__num { font-family: var(--font-sans); font-size: var(--fs-xs); color: var(--gold); }\n.option-card__label { font-family: var(--font-serif); font-size: var(--fs-md); }\n\n/* step 2 — calendar */\n.calendar { max-width: 420px; }\n.calendar__head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 1.2rem; }\n.calendar__month { font-family: var(--font-serif); font-size: var(--fs-md); }\n.calendar__nav { display: flex; gap: .6rem; }\n.calendar__nav button { width: 34px; height: 34px; border: 1px solid var(--line-dark); }\n.calendar__nav button:hover { border-color: var(--espresso); }\n.calendar__dow { display: grid; grid-template-columns: repeat(7,1fr); margin-bottom: .5rem; }\n.calendar__dow span { text-align: center; font-family: var(--font-sans); font-size: 10.5px; letter-spacing: .08em; color: rgba(21,16,12,.45); }\n.calendar__grid { display: grid; grid-template-columns: repeat(7,1fr); gap: 4px; }\n.calendar__day {\n  aspect-ratio: 1; display: flex; align-items: center; justify-content: center;\n  font-family: var(--font-sans); font-size: var(--fs-sm); border: 1px solid transparent;\n}\n.calendar__day.is-enabled:hover { border-color: var(--espresso); }\n.calendar__day.is-empty { visibility: hidden; }\n.calendar__day.is-unavailable { color: rgba(21,16,12,.28); text-decoration: line-through; cursor: not-allowed; }\n.calendar__day.is-past { color: rgba(21,16,12,.2); cursor: not-allowed; }\n.calendar__day.is-selected { background: var(--void); color: var(--ivory); }\n.calendar__legend { display: flex; gap: 1.4rem; margin-top: 1.4rem; font-family: var(--font-sans); font-size: var(--fs-xs); color: rgba(21,16,12,.55); }\n.calendar__legend span { display: inline-flex; align-items: center; gap: .5rem; }\n.calendar__legend i { width: 9px; height: 9px; display: inline-block; border: 1px solid var(--espresso); }\n.calendar__legend i.unavail { background: rgba(21,16,12,.15); border-color: transparent; text-decoration: line-through; }\n.calendar__selected-note { margin-top: 1.4rem; font-family: var(--font-sans); font-size: var(--fs-sm); }\n\n/* step 3 — experience/services select */\n.service-select { border-top: 1px solid var(--line-dark); }\n.service-option {\n  display: flex; align-items: center; justify-content: space-between; gap: 1rem;\n  padding: 1.4rem 0; border-bottom: 1px solid var(--line-dark); cursor: pointer;\n}\n.service-option__left { display: flex; align-items: center; gap: 1rem; }\n.service-option__radio { width: 18px; height: 18px; border: 1px solid var(--espresso); border-radius: 50%; position: relative; flex-shrink: 0; }\n.service-option__radio::after { content:\'\'; position: absolute; inset: 4px; background: var(--terracotta); border-radius: 50%; transform: scale(0); transition: transform .2s var(--ease); }\n.service-option.is-selected .service-option__radio::after { transform: scale(1); }\n.service-option__name { font-family: var(--font-serif); font-size: var(--fs-md); }\n.service-option__desc { font-family: var(--font-sans); font-size: var(--fs-xs); color: rgba(21,16,12,.55); }\n.service-option__price { font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .06em; color: var(--bronze); white-space: nowrap; }\n\n/* step 4 — form */\n.form-grid { display: grid; grid-template-columns: 1fr; gap: 1.6rem 1.6rem; }\n@media (min-width: 700px) { .form-grid { grid-template-columns: 1fr 1fr; } }\n.field { position: relative; }\n.field--full { grid-column: 1 / -1; }\n.field label { display: block; font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .08em; text-transform: uppercase; color: rgba(21,16,12,.55); margin-bottom: .6rem; }\n.field input, .field select, .field textarea {\n  width: 100%; border: none; border-bottom: 1px solid var(--line-dark); background: transparent;\n  padding: .7rem 0; font-family: var(--font-sans); font-size: var(--fs-base);\n  transition: border-color var(--dur-fast);\n}\n.field textarea { resize: vertical; min-height: 90px; }\n.field input:focus, .field select:focus, .field textarea:focus { border-color: var(--terracotta); outline: none; }\n.field input:invalid:not(:placeholder-shown) { border-color: var(--burgundy); }\n.field__hint { font-family: var(--font-sans); font-size: 11px; color: rgba(21,16,12,.4); margin-top: .4rem; }\n\n/* step 5 — review */\n.review-list { border-top: 1px solid var(--line-dark); margin-bottom: 2.4rem; }\n.review-row { display: flex; justify-content: space-between; gap: 1rem; padding: 1.1rem 0; border-bottom: 1px solid var(--line-dark); }\n.review-row dt { font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .08em; text-transform: uppercase; color: rgba(21,16,12,.5); }\n.review-row dd { font-family: var(--font-serif); font-size: var(--fs-md); text-align: right; max-width: 60%; }\n.review-edit { display: flex; justify-content: flex-end; margin-top: -1.6rem; margin-bottom: 2rem; }\n\n.booking__nav {\n  position: fixed; left: 0; right: 0; bottom: 0; z-index: 40;\n  display: flex; justify-content: space-between; align-items: center;\n  gap: 1rem; padding: 1rem var(--gutter); padding-bottom: max(1rem, env(safe-area-inset-bottom));\n  background: rgba(250,246,238,.94); backdrop-filter: blur(10px);\n  border-top: 1px solid var(--line-dark); box-shadow: 0 -8px 24px rgba(21,16,12,.06);\n}\n.booking__body { padding-bottom: clamp(6rem, 18vw, 8rem) !important; }\n.booking__back { font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .1em; text-transform: uppercase; color: rgba(21,16,12,.5); }\n.booking__back:hover { color: var(--void); }\n\n/* success */\n.booking__success { display: none; flex: 1; align-items: center; justify-content: center; text-align: center; padding: 4rem var(--gutter); }\n.booking__success.is-active { display: flex; }\n.booking__success-inner { max-width: 520px; }\n.booking__success .accent-dot { display: inline-block; }\n\n/* ==========================================================================\n   14. TESTIMONIALS — the most luxurious spot on the site\n   ========================================================================== */\n.testimonials { position: relative; background: linear-gradient(165deg, var(--espresso) 0%, var(--void) 78%); color: var(--ivory); overflow: hidden; }\n.testimonials__mark {\n  position: absolute; top: -8%; left: 50%; transform: translateX(-50%); z-index: 0; pointer-events: none;\n  font-family: var(--font-serif); font-size: clamp(14rem,32vw,26rem); line-height: 1; color: var(--gold); opacity: .07;\n}\n.testimonials__grid { position: relative; z-index: 1; display: grid; grid-template-columns: 1fr; gap: clamp(2.2rem,5vw,3.5rem); align-items: center; }\n.testimonials__portrait { position: relative; width: 100%; max-width: 320px; aspect-ratio: 3/4; margin-inline: auto; }\n.testimonials__portrait::after { content: \'\'; position: absolute; inset: 10px; border: 1px solid var(--gold-soft); opacity: .55; pointer-events: none; z-index: 2; }\n.testimonials__portrait .media-frame__art { position: absolute; inset: 0; opacity: 0; transition: opacity .7s var(--ease-soft); }\n.testimonials__portrait .media-frame__art.is-active { opacity: 1; }\n.testimonials__quote-mark { display: block; font-family: var(--font-serif); font-size: clamp(3.5rem,7vw,5.5rem); line-height: .6; color: var(--gold); margin-bottom: .6rem; }\n.testimonial { display: none; }\n.testimonial.is-active { display: block; animation: testFade .8s var(--ease); }\n@keyframes testFade { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }\n@media (prefers-reduced-motion: reduce) { .testimonial.is-active { animation: none; } }\n.testimonial blockquote { font-family: var(--font-serif); font-style: italic; font-weight: 400; font-size: clamp(1.6rem,3vw,2.5rem); line-height: 1.4; max-width: 26ch; }\n.testimonial__meta { display: flex; align-items: center; gap: 1rem; margin-top: 2rem; }\n.testimonial__meta-line { width: 32px; height: 1px; background: var(--gold-soft); flex-shrink: 0; }\n.testimonial cite { font-style: normal; font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .12em; text-transform: uppercase; color: var(--gold-soft); }\n.testimonials__nav { display: flex; align-items: center; gap: 1.2rem; margin-top: clamp(2rem,4vw,3rem); }\n.testimonials__count { font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .1em; color: rgba(242,233,216,.5); min-width: 50px; }\n.testimonials__arrow { width: 40px; height: 40px; border: 1px solid var(--line-light); display: flex; align-items: center; justify-content: center; transition: background var(--dur-fast), border-color var(--dur-fast), color var(--dur-fast); }\n.testimonials__arrow:hover { background: var(--gold); border-color: var(--gold); color: var(--void); }\n.testimonials__note { margin-top: 1.3rem; font-family: var(--font-sans); font-size: 11px; letter-spacing: .06em; color: rgba(242,233,216,.4); }\n@media (min-width: 860px) {\n  .testimonials__grid { grid-template-columns: 300px 1fr; }\n  .testimonials__portrait { margin-inline: 0; }\n}\n\n/* ==========================================================================\n   15. SOCIAL PROOF\n   ========================================================================== */\n.proof { background: var(--cream); border-top: 1px solid var(--line-dark); border-bottom: 1px solid var(--line-dark); }\n.proof__row { display: grid; grid-template-columns: repeat(2,1fr); }\n@media (min-width: 760px) { .proof__row { grid-template-columns: repeat(4,1fr); } }\n.proof__item { padding: clamp(1.8rem,4vw,3rem) 1rem; text-align: center; border-right: 1px solid var(--line-dark); border-bottom: 1px solid var(--line-dark); }\n.proof__row .proof__item:nth-child(2n) { border-right: none; }\n@media (min-width: 760px) { .proof__row .proof__item:nth-child(2n) { border-right: 1px solid var(--line-dark); } .proof__row .proof__item:nth-child(4n) { border-right: none; } .proof__item { border-bottom: none; } }\n.proof__item span { font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .14em; text-transform: uppercase; color: rgba(21,16,12,.55); }\n.proof__sub { margin-top: .5rem; font-family: var(--font-serif); font-style: italic; font-size: var(--fs-sm); color: rgba(21,16,12,.4); }\n\n/* ==========================================================================\n   16. JOURNAL\n   ========================================================================== */\n.journal { background: var(--cream); }\n.journal-media { display: grid; grid-template-columns: repeat(2,1fr); gap: clamp(.5rem,1.5vw,1rem); }\n@media (min-width: 700px) { .journal-media { grid-template-columns: repeat(4,1fr); } }\n.journal-media__item { position: relative; aspect-ratio: 3/4; overflow: hidden; background: var(--espresso); cursor: pointer; }\n.journal-media__item video, .journal-media__item img { width: 100%; height: 100%; object-fit: cover; }\n.has-motion .journal-media__item img { animation: ambientZoomSlow 20s ease-in-out infinite alternate; }\n@keyframes ambientZoomSlow { from { transform: scale(1); } to { transform: scale(1.07); } }\n.journal-media__play {\n  position: absolute; top: .8rem; right: .8rem; width: 30px; height: 30px; border-radius: 50%;\n  background: rgba(13,10,7,.55); display: flex; align-items: center; justify-content: center; color: var(--ivory); pointer-events: none;\n}\n.journal-media__play svg { width: 11px; height: 11px; margin-left: 1px; }\n.journal__item {\n  display: grid; grid-template-columns: 90px 1fr; gap: 1.4rem; align-items: center;\n  padding: clamp(1.4rem,3vw,2rem) 0; border-bottom: 1px solid var(--line-dark);\n}\n.journal__thumb { aspect-ratio: 1; }\n.journal__cat { color: var(--gold); }\n.journal__title { font-family: var(--font-serif); font-size: clamp(1.3rem,2.4vw,1.9rem); margin-block: .3rem; transition: color var(--dur-fast); }\n.journal__item:hover .journal__title { color: var(--terracotta); }\n.journal__excerpt { display: none; max-width: 56ch; font-family: var(--font-sans); font-size: var(--fs-sm); color: rgba(21,16,12,.6); }\n@media (min-width: 700px) {\n  .journal__item { grid-template-columns: 120px 1fr auto; }\n  .journal__excerpt { display: block; }\n}\n\n/* ==========================================================================\n   17. INSTAGRAM\n   ========================================================================== */\n.instagram { background: var(--ivory); }\n.instagram__grid { display: grid; grid-template-columns: repeat(3,1fr); gap: clamp(.4rem,1vw,.8rem); }\n@media (min-width: 700px) { .instagram__grid { grid-template-columns: repeat(6,1fr); } }\n.instagram__item { aspect-ratio: 1; position: relative; overflow: hidden; transition: transform .25s var(--ease-soft); transform-style: preserve-3d; will-change: transform; }\n.instagram__item .media-frame__art { transition: filter .6s var(--ease); }\n.instagram__item:hover .media-frame__art { filter: brightness(1.1); }\n.instagram__item::after { content: \'♡\'; position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; color: var(--ivory); font-size: 1.4rem; background: rgba(21,16,12,0); transition: background var(--dur-fast); opacity: 0; }\n.instagram__item:hover::after { opacity: 1; background: rgba(21,16,12,.32); }\n\n/* ==========================================================================\n   18. FINAL CTA\n   ========================================================================== */\n.final-cta { position: relative; min-height: 100svh; display: flex; align-items: center; justify-content: center; background: var(--void); color: var(--ivory); overflow: hidden; text-align: center; }\n.final-cta__media { position: absolute; inset: 0; opacity: .55; }\n.final-cta__media .media-frame__art { transform: scale(1.08); transition: transform 6s var(--ease-soft); }\n.final-cta.is-in-view .media-frame__art { transform: scale(1); }\n.final-cta__scrim { position: absolute; inset: 0; background: radial-gradient(ellipse at center, rgba(21,16,12,.35), rgba(21,16,12,.88)); }\n.final-cta__content { position: relative; z-index: 2; display: grid; gap: 2.2rem; justify-items: center; padding-inline: var(--gutter); }\n.final-cta__headline { font-family: var(--font-serif); font-size: var(--fs-display); line-height: .94; }\n.final-cta__headline .line { display: block; overflow: hidden; }\n.final-cta__headline .line span { display: block; transform: translateY(105%); }\n\n/* ==========================================================================\n   19. FOOTER\n   ========================================================================== */\n.footer { background: var(--void); color: var(--ivory); padding-top: clamp(3.5rem,7vw,6rem); }\n.footer__logo-mark { width: clamp(2rem,4vw,2.6rem); height: clamp(2rem,4vw,2.6rem); color: var(--gold); margin-bottom: 1rem; }\n.footer__mark { font-family: var(--font-serif); font-size: clamp(3rem,10vw,7.5rem); line-height: .92; margin-bottom: clamp(2.5rem,5vw,4rem); }\n.footer__grid { display: grid; gap: 2.4rem; grid-template-columns: 1fr; padding-bottom: 3rem; border-bottom: 1px solid var(--line-light); }\n@media (min-width: 760px) { .footer__grid { grid-template-columns: repeat(4,1fr); } }\n.footer__col h4 { font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .12em; text-transform: uppercase; color: var(--gold); margin-bottom: 1rem; }\n.footer__col a, .footer__col p { display: block; font-family: var(--font-sans); font-size: var(--fs-sm); color: rgba(242,233,216,.75); margin-bottom: .6rem; }\n.footer__col a:hover { color: var(--ivory); }\n.footer__bottom { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 1rem; padding-block: 1.6rem; font-family: var(--font-sans); font-size: var(--fs-xs); color: rgba(242,233,216,.45); }\n.footer__bottom a { color: rgba(242,233,216,.45); }\n.footer__bottom a:hover { color: var(--ivory); }\n.footer__legal { display: flex; gap: 1.4rem; }\n\n/* ==========================================================================\n   20. SCROLL-REVEAL SYSTEM (progressive enhancement — see JS)\n   ========================================================================== */\n.has-motion .reveal-mask .line span,\n.has-motion .hero__headline .line span,\n.has-motion .final-cta__headline .line span,\n.has-motion .loader__mark span { transform: translateY(105%); }\n.has-motion .reveal-mask:not(.hero__headline) .line span {\n  transition: transform .9s cubic-bezier(.16,1,.3,1);\n}\n.has-motion .reveal-mask:not(.hero__headline).is-revealed .line span { transform: translateY(0%); }\n.has-motion .reveal-mask:not(.hero__headline) .line:nth-child(2) span { transition-delay: .08s; }\n.has-motion .reveal-mask:not(.hero__headline) .line:nth-child(3) span { transition-delay: .16s; }\n.has-motion .reveal-mask:not(.hero__headline) .line:nth-child(4) span { transition-delay: .24s; }\n.has-motion [data-reveal] { opacity: 0; transform: translateY(28px); transition: opacity .9s var(--ease), transform .9s var(--ease); }\n.has-motion [data-reveal].is-revealed { opacity: 1; transform: none; }\n.has-motion [data-reveal-scale] { opacity: 0; transform: scale(.92); transition: opacity 1s var(--ease), transform 1.1s var(--ease); }\n.has-motion [data-reveal-scale].is-revealed { opacity: 1; transform: scale(1); }\nbody.modal-open { overflow: hidden; }\n\n@media (max-width: 480px) {\n  .display-1 { letter-spacing: -0.02em; }\n  .btn { padding: 1rem 1.4rem; font-size: 11.5px; }\n}\n\n/* ==========================================================================\n   21a. DISSOLVE — slow seamless crossfade between two images\n   ========================================================================== */\n.dissolve { position: relative; width: 100%; height: 100%; z-index: 1; }\n.dissolve img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }\n.has-motion .dissolve img:first-child { animation: dissolveA 18s ease-in-out infinite; }\n.has-motion .dissolve img:last-child { animation: dissolveB 18s ease-in-out infinite; }\n@keyframes dissolveA { 0%,45% { opacity: 1; } 50%,95% { opacity: 0; } 100% { opacity: 1; } }\n@keyframes dissolveB { 0%,45% { opacity: 0; } 50%,95% { opacity: 1; } 100% { opacity: 0; } }\n.dissolve__credit {\n  position: absolute; left: 0; right: 0; bottom: 0; z-index: 5;\n  padding: 1.6rem 1.2rem 1.1rem; background: linear-gradient(0deg, rgba(0,0,0,.8) 0%, transparent 100%);\n  font-family: var(--font-sans); font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase;\n  color: var(--ivory);\n}\n.dissolve__credit span { display: block; margin-top: .3em; font-weight: 500; letter-spacing: .04em; text-transform: none; color: rgba(242,233,216,.7); }\n\n/* ==========================================================================\n   21b. PAGE OPENER — shared editorial header used atop inner views\n   ========================================================================== */\n.page-opener { padding-top: clamp(3rem,7vw,5.5rem); padding-bottom: clamp(1.5rem,4vw,2.5rem); }\n.page-opener__lede { margin-top: 1.2rem; max-width: 56ch; }\n\n/* ==========================================================================\n   21c. ACHIEVEMENTS\n   ========================================================================== */\n.achievement { display: grid; gap: clamp(1.5rem,4vw,3rem); padding-block: clamp(2.5rem,5vw,4.5rem); border-top: 1px solid var(--line-light); align-items: start; }\n.achievements-list > .achievement:last-child { border-bottom: 1px solid var(--line-light); }\n.achievement__num { font-family: var(--font-serif); font-size: clamp(3rem,7vw,5.5rem); line-height: .8; color: transparent; -webkit-text-stroke: 1px var(--gold-soft); }\n.achievement__media { aspect-ratio: 16/10; }\n.achievement__body h3 { margin-bottom: .8rem; }\n.achievement__venues { display: flex; flex-wrap: wrap; gap: .6rem; margin-top: 1.2rem; }\n.achievement__venues span {\n  font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .06em;\n  padding: .5rem .9rem; border: 1px solid var(--line-light); color: rgba(242,233,216,.8);\n}\n.social-buzz {\n  display: flex; gap: 1.1rem; align-items: center; margin-top: 1.6rem;\n  padding: 1rem; border: 1px solid var(--line-light); max-width: 34rem;\n}\n.social-buzz__media { flex: none; width: 64px; height: 64px; border-radius: 50%; overflow: hidden; }\n.social-buzz__media img { width: 100%; height: 100%; object-fit: cover; object-position: 50% 20%; }\n.social-buzz__source {\n  display: block; font-family: var(--font-sans); font-size: 10px; letter-spacing: .12em; text-transform: uppercase;\n  color: var(--gold-soft); margin-bottom: .3rem;\n}\n.social-buzz__quote { font-family: var(--font-serif); font-style: italic; font-size: var(--fs-sm); color: var(--ivory); line-height: 1.35; }\n.social-buzz__handle { display: block; font-family: var(--font-sans); font-size: 11px; color: rgba(242,233,216,.55); margin-top: .3rem; }\n@media (min-width: 780px) {\n  .achievement { grid-template-columns: 90px 1fr 1fr; }\n}\n\n/* ==========================================================================\n   21. CLASSES SECTION\n   ========================================================================== */\n.classes__intro { max-width: 60ch; }\n.classes__list { border-top: 1px solid var(--line-dark); margin-top: clamp(2.5rem,5vw,4rem); }\n.classes__item {\n  display: grid; grid-template-columns: 1fr; gap: 1.4rem;\n  padding: clamp(2rem,4vw,3rem) 0; border-bottom: 1px solid var(--line-dark);\n}\n.classes__media { aspect-ratio: 4/3; transition: transform .25s var(--ease-soft); transform-style: preserve-3d; will-change: transform; }\n.classes__head { display: flex; justify-content: space-between; align-items: baseline; gap: 1rem; margin-bottom: .6rem; }\n.classes__price { font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .06em; color: var(--bronze); white-space: nowrap; }\n@media (min-width: 780px) {\n  .classes__item { grid-template-columns: 320px 1fr; align-items: center; gap: 2.4rem; }\n}\n.classes__note { margin-top: clamp(2rem,4vw,3rem); font-family: var(--font-sans); font-size: var(--fs-sm); color: rgba(21,16,12,.55); max-width: 60ch; }\n\n/* ==========================================================================\n   25. LOGO\n   ========================================================================== */\n.nav__logo { display: inline-flex; align-items: center; gap: .55rem; }\n.nav__logo svg { width: 20px; height: 20px; flex-shrink: 0; color: var(--gold); }\n.footer__mark-lockup { display: flex; align-items: center; gap: 1.1rem; margin-bottom: clamp(2rem,5vw,3.5rem); }\n.footer__mark-lockup svg { width: clamp(2.4rem,6vw,3.8rem); height: clamp(2.4rem,6vw,3.8rem); color: var(--gold); flex-shrink: 0; }\n\n/* ==========================================================================\n   26. MEDIA GALLERY (Journal reimagined as pictures + video)\n   ========================================================================== */\n.media-gallery { display: grid; grid-template-columns: repeat(2,1fr); gap: clamp(.5rem,1.2vw,1rem); }\n@media (min-width: 700px) { .media-gallery { grid-template-columns: repeat(3,1fr); } }\n.media-gallery__item { position: relative; aspect-ratio: 3/4; overflow: hidden; background: var(--espresso); }\n.media-gallery__item video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }\n.media-gallery__badge {\n  position: absolute; top: .7rem; right: .7rem; z-index: 2; width: 28px; height: 28px; border-radius: 50%;\n  background: rgba(21,16,12,.55); backdrop-filter: blur(4px); display: flex; align-items: center; justify-content: center; color: var(--ivory);\n}\n.media-gallery__badge svg { width: 12px; height: 12px; }\n.media-gallery__caption {\n  position: absolute; left: 0; right: 0; bottom: 0; z-index: 2; padding: 1rem .9rem .8rem;\n  background: linear-gradient(0deg, rgba(0,0,0,.72), transparent);\n}\n.media-gallery__caption p { font-family: var(--font-sans); font-size: 10px; letter-spacing: .1em; text-transform: uppercase; color: var(--ivory); }\n.media-gallery__caption p:first-child { color: var(--gold-soft); font-weight: 700; margin-bottom: .2em; }\n\n/* ==========================================================================\n   27. FOUNDER (About page, rebuilt around the owner)\n   ========================================================================== */\n.founder { display: grid; gap: clamp(2rem,5vw,3.5rem); align-items: center; }\n@media (min-width: 860px) { .founder { grid-template-columns: .85fr 1.15fr; } }\n.founder__portrait { aspect-ratio: 4/5; }\n.founder__quote { border-left: 1px solid var(--gold); padding-left: 1.4rem; margin-top: 1.6rem; }\n.founder-strip { display: grid; grid-template-columns: repeat(2,1fr); gap: .7rem; margin-top: clamp(2rem,4vw,3.5rem); }\n@media (min-width: 700px) { .founder-strip { grid-template-columns: repeat(3,1fr); } }\n.founder-strip__item { aspect-ratio: 4/5; position: relative; overflow: hidden; transition: transform .25s var(--ease-soft); transform-style: preserve-3d; will-change: transform; }\n.founder-strip__item span {\n  position: absolute; left: 0; right: 0; bottom: 0; padding: .7rem .6rem;\n  background: linear-gradient(0deg, rgba(0,0,0,.72), transparent);\n  font-family: var(--font-sans); font-size: 9.5px; letter-spacing: .08em; text-transform: uppercase; color: var(--ivory);\n}\n\n/* extra insurance for legibility once a busy video sits behind the hero text */\n.hero__scrim { background:\n    linear-gradient(0deg, rgba(13,10,7,.97) 0%, rgba(13,10,7,.7) 34%, rgba(13,10,7,.45) 58%, rgba(13,10,7,.65) 100%),\n    linear-gradient(100deg, rgba(13,10,7,.6) 0%, rgba(13,10,7,0) 42%); }\n\n/* hero ghost button — light text, this section is always dark */\n.hero .btn--ghost { color: var(--ivory); }\n.hero .btn--ghost:hover { background: var(--ivory); color: var(--void); }\n\n/* keeps the nav readable over the hero regardless of what the video is showing at any moment */\n.nav:not(.is-scrolled) .nav__logo,\n.nav:not(.is-scrolled) .nav__link {\n  text-shadow: 0 1px 12px rgba(0,0,0,.55), 0 1px 2px rgba(0,0,0,.5);\n}\n\n/* ==========================================================================\n   28. SERVICES — full editorial redesign\n   ========================================================================== */\n.service-feature__block { display: grid; grid-template-columns: 1fr; }\n@media (min-width: 900px) { .service-feature__block { grid-template-columns: 1fr 1fr; min-height: 78vh; } }\n.service-feature__block:nth-child(even) .service-feature__media { order: 2; }\n.service-feature__media { position: relative; aspect-ratio: 4/5; overflow: hidden; }\n@media (min-width: 900px) { .service-feature__media { aspect-ratio: auto; } }\n.service-feature__body {\n  display: flex; flex-direction: column; justify-content: center;\n  padding: clamp(2.5rem,6vw,5.5rem) var(--gutter);\n  background: var(--cream);\n}\n.service-feature__block:nth-child(odd) .service-feature__body { background: var(--ivory); }\n.service-feature__num {\n  font-family: var(--font-serif); font-size: clamp(2.2rem,4.5vw,3.4rem); line-height: 1;\n  color: transparent; -webkit-text-stroke: 1px var(--gold-soft); margin-bottom: 1.2rem;\n}\n.service-feature__tag {\n  display: inline-block; font-family: var(--font-sans); font-size: var(--fs-xs); font-weight: 700;\n  letter-spacing: .14em; text-transform: uppercase; color: var(--bronze); margin-bottom: .8rem;\n}\n.service-feature__title { font-family: var(--font-serif); font-size: clamp(2.2rem,4vw,3.2rem); line-height: 1.05; }\n.service-feature__desc { margin-top: 1.2rem; max-width: 44ch; }\n.service-feature__cta { margin-top: 1.8rem; }\n\n/* ==========================================================================\n   29. PAGE HERO — reusable banner for inner pages (Classes, etc.)\n   ========================================================================== */\n.page-hero { position: relative; height: 62vh; min-height: 440px; display: flex; align-items: flex-end; overflow: hidden; color: var(--ivory); }\n.page-hero__media { position: absolute; inset: 0; }\n.page-hero__media img { width: 100%; height: 100%; object-fit: cover; }\n.page-hero__scrim {\n  position: absolute; inset: 0;\n  background: linear-gradient(0deg, rgba(13,10,7,.92) 0%, rgba(13,10,7,.32) 55%, rgba(13,10,7,.55) 100%);\n}\n.page-hero__content { position: relative; z-index: 2; width: 100%; padding: clamp(2rem,5vw,3.5rem) var(--gutter) clamp(2.5rem,5vw,4rem); }\n\n/* Featured guest block (e.g. a named masterclass collaborator) */\n.guest-feature { display: grid; gap: clamp(1.8rem,4vw,3rem); align-items: center; }\n@media (min-width: 860px) { .guest-feature { grid-template-columns: .8fr 1.2fr; } }\n.guest-feature__media { aspect-ratio: 4/5; }\n.guest-feature__media[data-placeholder] .media-frame__tag { font-size: 11px; }\n\n/* ==========================================================================\n   30. FINAL CTA — floating vertical video insert\n   ========================================================================== */\n.final-cta__reel {\n  display: none;\n  position: absolute; z-index: 3; width: clamp(150px, 16vw, 240px); aspect-ratio: 9/16;\n  overflow: hidden; border: 2px solid rgba(255,255,255,.18);\n  box-shadow: 0 30px 70px -20px rgba(0,0,0,.7);\n  bottom: clamp(2rem,6vw,4rem); right: clamp(1.5rem,7vw,6rem);\n}\n@media (min-width: 760px) { .final-cta__reel { display: block; } }\n.final-cta__reel video { width: 100%; height: 100%; object-fit: cover; }\n\n/* ==========================================================================\n   31. LOADER EXIT — filmstrip-style shutter sweep instead of a flat fade\n   ========================================================================== */\n.loader__shutter { position: absolute; inset: 0; z-index: 1; display: flex; }\n.loader__shutter span { flex: 1 1 0; background: var(--void); transform: scaleY(1); transform-origin: bottom; }\n.loader__shutter span + span { border-left: 1px solid rgba(255,255,255,.06); }\n@keyframes loaderShutterOpen { to { transform: scaleY(0); } }\n.has-motion .loader__shutter span {\n  animation-name: loaderShutterOpen; animation-duration: .6s;\n  animation-timing-function: cubic-bezier(.65,0,.35,1); animation-fill-mode: forwards;\n  animation-delay: 1.65s;\n}\n.has-motion .loader__shutter span:nth-child(2) { animation-delay: 1.7s; }\n.has-motion .loader__shutter span:nth-child(3) { animation-delay: 1.75s; }\n.has-motion .loader__shutter span:nth-child(4) { animation-delay: 1.8s; }\n.has-motion .loader__shutter span:nth-child(5) { animation-delay: 1.85s; }\n.has-motion .loader__shutter span:nth-child(6) { animation-delay: 1.9s; }\n.loader__mark, .loader__bar { position: relative; z-index: 2; }\n\n/* ==========================================================================\n   32. CONTACT — elevated layout\n   ========================================================================== */\n.contact-split { display: grid; gap: 0; grid-template-columns: 1fr; }\n@media (min-width: 900px) { .contact-split { grid-template-columns: .9fr 1.1fr; align-items: stretch; } }\n.contact-split__media { position: relative; aspect-ratio: 4/5; overflow: hidden; }\n@media (min-width: 900px) { .contact-split__media { aspect-ratio: auto; min-height: 640px; } }\n.contact-split__media-quote {\n  position: absolute; left: 0; right: 0; bottom: 0; z-index: 2; padding: clamp(1.6rem,4vw,2.6rem);\n  background: linear-gradient(0deg, rgba(0,0,0,.78) 0%, transparent 100%);\n}\n.contact-split__media-quote p {\n  font-family: var(--font-serif); font-style: italic; font-size: clamp(1.15rem,2.2vw,1.5rem);\n  color: var(--ivory); line-height: 1.35; max-width: 30ch;\n}\n.contact-split__body { background: var(--cream); padding: clamp(2.5rem,6vw,4.5rem) var(--gutter); display: flex; flex-direction: column; justify-content: center; }\n.contact-split__form-card {\n  margin-top: clamp(2rem,4vw,3rem); padding: clamp(1.8rem,4vw,2.8rem);\n  border: 1px solid var(--line-dark); position: relative;\n}\n.contact-split__form-card::before {\n  content: ""; position: absolute; top: -1px; left: clamp(1.8rem,4vw,2.8rem); width: 44px; height: 3px; background: var(--gold);\n}\n\n.contact-methods { display: grid; grid-template-columns: 1fr; gap: 0; margin-top: clamp(1.6rem,3vw,2.2rem); }\n@media (min-width: 640px) { .contact-methods { grid-template-columns: repeat(3,1fr); } }\n.contact-methods__item {\n  padding: 1.4rem 0; border-top: 1px solid var(--line-dark);\n}\n@media (min-width: 640px) { .contact-methods__item { padding: 0 1.6rem; border-top: none; border-left: 1px solid var(--line-dark); } }\n.contact-methods__item:first-child { border: none; padding-left: 0; }\n.contact-methods__num {\n  font-family: var(--font-serif); font-size: 1.6rem; line-height: 1;\n  color: transparent; -webkit-text-stroke: 1px var(--gold-soft); display: block; margin-bottom: .6rem;\n}\n.contact-methods__item h4 { font-family: var(--font-sans); font-size: var(--fs-xs); letter-spacing: .1em; text-transform: uppercase; color: rgba(21,16,12,.5); margin-bottom: .5rem; }\n\n/* ==========================================================================\n   33. LOGO MARK — draw-on-scroll signature moment (footer)\n   ========================================================================== */\n.logo-mark--draw path {\n  transition: stroke-dashoffset 1.1s cubic-bezier(.22,1,.36,1);\n}\n.logo-mark--draw path:nth-of-type(2) { transition-delay: .15s; }\n.logo-mark--draw path:nth-of-type(3) { transition-delay: .3s; }\n.logo-mark--draw circle {\n  opacity: 0; transform-origin: 35px 8px; transform: scale(.2);\n  transition: opacity .5s ease, transform .5s cubic-bezier(.34,1.56,.64,1) .95s;\n}\n.logo-mark--draw.is-drawn path { stroke-dashoffset: 0; }\n.logo-mark--draw.is-drawn circle { opacity: 1; transform: scale(1); }\n\n/* ==========================================================================\n   34. BACK TO TOP\n   ========================================================================== */\n.back-to-top {\n  position: fixed; right: clamp(1.2rem,3vw,2.2rem); bottom: clamp(1.2rem,3vw,2.2rem); z-index: 500;\n  width: 48px; height: 48px; border-radius: 50%;\n  background: var(--void); color: var(--ivory); border: 1px solid rgba(215,171,110,.4);\n  display: flex; align-items: center; justify-content: center;\n  opacity: 0; visibility: hidden; transform: translateY(12px);\n  transition: opacity .35s var(--ease-soft), transform .35s var(--ease-soft), visibility .35s, background .25s, border-color .25s;\n  cursor: pointer;\n}\n.back-to-top svg { width: 18px; height: 18px; }\n.back-to-top.is-visible { opacity: 1; visibility: visible; transform: translateY(0); }\n.back-to-top:hover { background: var(--gold); color: var(--void); border-color: var(--gold); }\n');
write('app/journal/page.js', 'import { JOURNAL_MEDIA } from "@/lib/data";\nimport ClassesScripts from "@/components/ClassesScripts";\n\nexport const metadata = {\n  title: "Journal: Gele Glamzzz | Pictures & Video from the Studio",\n  description: "A live feed of pictures and video from Gele Glamzzz: finished looks, behind the fold, and moments from the studio.",\n  keywords: ["gele styling photos", "gele behind the scenes", "gele video London"],\n  alternates: { canonical: "/journal" },\n};\n\nfunction PlayIcon() {\n  return (\n    <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">\n      <path d="M8 5v14l11-7z" />\n    </svg>\n  );\n}\n\nexport default function JournalPage() {\n  return (\n    <>\n      <section className="page-opener">\n        <div className="container container--narrow">\n          <span className="eyebrow" data-reveal>The Journal</span>\n          <h1 className="h2" data-reveal style={{ marginTop: ".8rem" }}>Notes on the art<br />of the crown.</h1>\n          <p className="lede page-opener__lede" data-reveal>A live feed of pictures and video from the studio, no articles to read, just the work itself.</p>\n        </div>\n      </section>\n\n      <section className="section-pad" style={{ paddingTop: "clamp(1rem,3vw,2rem)" }}>\n        <div className="container">\n          <div className="media-gallery" data-reveal-scale>\n            {JOURNAL_MEDIA.map((m, i) => (\n              <div key={i} className="media-gallery__item">\n                {m.type === "video" ? (\n                  <>\n                    {/* TODO(video): drop an .mp4 at the path in `suggest` (see lib/data.js) and set `src` — it will autoplay muted, looped, with no controls, exactly as is. Until then the poster frame shows. */}\n                    <video muted loop autoPlay playsInline preload="metadata" poster={m.poster} aria-label={m.caption}>\n                      {m.src && <source src={m.src} type="video/mp4" />}\n                    </video>\n                    <span className="media-gallery__badge"><PlayIcon /></span>\n                  </>\n                ) : (\n                  <img src={m.src} alt={m.caption} loading="lazy" style={{ width: "100%", height: "100%", objectFit: "cover" }} />\n                )}\n                <span className="media-gallery__caption"><p>{m.sub}</p><p>{m.caption}</p></span>\n              </div>\n            ))}\n          </div>\n        </div>\n      </section>\n\n      <ClassesScripts />\n    </>\n  );\n}\n');
write('components/BookingClient.js', '"use client";\nimport { useState, useMemo } from "react";\nimport useReveal from "@/lib/useReveal";\nimport { SERVICES } from "@/lib/data";\n\nconst STEP_NAMES = ["Your Occasion", "Your Date", "Your Experience", "Your Details", "Review & Send"];\nconst MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];\nconst OCCASIONS = ["Bridal", "Traditional Ceremony", "Birthday / Celebration", "Photoshoot", "Corporate Workshop", "Other"];\n\nfunction pad(n) { return n < 10 ? "0" + n : "" + n; }\nfunction isoDate(y, m, d) { return `${y}-${pad(m + 1)}-${pad(d)}`; }\n\nexport default function BookingPage() {\n  useReveal();\n  const today = useMemo(() => { const t = new Date(); t.setHours(0, 0, 0, 0); return t; }, []);\n  const [step, setStep] = useState(1);\n  const [occasion, setOccasion] = useState(null);\n  const [date, setDate] = useState(null);\n  const [dateLabel, setDateLabel] = useState("");\n  const [service, setService] = useState(null);\n  const [form, setForm] = useState({ name: "", email: "", phone: "", time: "", location: "", people: 1, notes: "" });\n  const [calMonth, setCalMonth] = useState({ y: today.getFullYear(), m: today.getMonth() });\n  const [submitted, setSubmitted] = useState(false);\n  const [submitting, setSubmitting] = useState(false);\n  const [submitError, setSubmitError] = useState("");\n  const [formError, setFormError] = useState(false);\n\n  function goTo(n) { setStep(n); if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: window.__prefersReducedMotion ? "auto" : "smooth" }); }\n\n  const canContinue =\n    (step === 1 && !!occasion) ||\n    (step === 2 && !!date) ||\n    (step === 3 && !!service) ||\n    step === 4 || step === 5;\n\n  function handleNext() {\n    if (step === 4) {\n      if (!form.name || !form.email || !form.phone || !form.location) { setFormError(true); return; }\n      setFormError(false);\n    }\n    if (step < 5) goTo(step + 1);\n  }\n\n  async function handleSubmit() {\n    setSubmitting(true);\n    setSubmitError("");\n    try {\n      const res = await fetch("/api/booking", {\n        method: "POST",\n        headers: { "Content-Type": "application/json" },\n        body: JSON.stringify({ occasion, dateLabel, serviceTitle: service, form }),\n      });\n      const data = await res.json();\n      if (!res.ok) {\n        setSubmitError(data.error || "Something went wrong. Please try again.");\n        setSubmitting(false);\n        return;\n      }\n      setSubmitted(true);\n      if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: window.__prefersReducedMotion ? "auto" : "smooth" });\n    } catch {\n      setSubmitError("Could not reach the server. Please check your connection and try again.");\n    } finally {\n      setSubmitting(false);\n    }\n  }\n\n  function resetAll() {\n    setSubmitted(false); setStep(1); setOccasion(null); setDate(null); setDateLabel("");\n    setService(null); setForm({ name: "", email: "", phone: "", time: "", location: "", people: 1, notes: "" });\n  }\n\n  const daysInMonth = new Date(calMonth.y, calMonth.m + 1, 0).getDate();\n  const firstDay = new Date(calMonth.y, calMonth.m, 1).getDay();\n\n  return (\n    <div className="booking-page">\n      <div className="booking-page__sticky">\n        <div className="booking__progress" aria-hidden="true">\n          {[1, 2, 3, 4, 5].map((n) => (\n            <div key={n} className={`booking__progress-seg${n < step ? " is-done" : n === step ? " is-active" : ""}`}><span></span></div>\n          ))}\n        </div>\n        <div className="booking__step-label"><span>Step 0{step} / 05</span><span>{STEP_NAMES[step - 1]}</span></div>\n      </div>\n\n      <div className="booking__body">\n        {!submitted && (\n          <>\n            {step === 1 && (\n              <div className="booking__step is-active">\n                <p className="eyebrow booking__kicker">Step 01</p>\n                <h1 className="h3 booking__title">What are you booking for?</h1>\n                <div className="option-grid" role="radiogroup" aria-label="Occasion type">\n                  {OCCASIONS.map((o, i) => (\n                    <button key={o} type="button" className={`option-card${occasion === o ? " is-selected" : ""}`} role="radio" aria-checked={occasion === o} onClick={() => setOccasion(o)}>\n                      <span className="option-card__num">{pad(i + 1)}</span>\n                      <span className="option-card__label">{o}</span>\n                    </button>\n                  ))}\n                </div>\n              </div>\n            )}\n\n            {step === 2 && (\n              <div className="booking__step is-active">\n                <p className="eyebrow booking__kicker">Step 02</p>\n                <h1 className="h3 booking__title">Choose your date.</h1>\n                <div className="calendar">\n                  <div className="calendar__head">\n                    <button type="button" aria-label="Previous month" onClick={() => setCalMonth((c) => (c.m === 0 ? { y: c.y - 1, m: 11 } : { y: c.y, m: c.m - 1 }))}>←</button>\n                    <span className="calendar__month">{MONTH_NAMES[calMonth.m]} {calMonth.y}</span>\n                    <div className="calendar__nav"><button type="button" aria-label="Next month" onClick={() => setCalMonth((c) => (c.m === 11 ? { y: c.y + 1, m: 0 } : { y: c.y, m: c.m + 1 }))}>→</button></div>\n                  </div>\n                  <div className="calendar__dow">{["S", "M", "T", "W", "T", "F", "S"].map((d, i) => <span key={i}>{d}</span>)}</div>\n                  <div className="calendar__grid">\n                    {Array.from({ length: firstDay }).map((_, i) => <span key={"e" + i} className="calendar__day is-empty"></span>)}\n                    {Array.from({ length: daysInMonth }).map((_, i) => {\n                      const d = i + 1;\n                      const iso = isoDate(calMonth.y, calMonth.m, d);\n                      const thisDate = new Date(calMonth.y, calMonth.m, d);\n                      const isPast = thisDate < today;\n                      const isSelected = date === iso;\n                      return (\n                        <button key={d} type="button" disabled={isPast}\n                          className={`calendar__day${isPast ? " is-past" : " is-enabled"}${isSelected ? " is-selected" : ""}`}\n                          onClick={() => { setDate(iso); setDateLabel(thisDate.toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long", year: "numeric" })); }}>\n                          {d}\n                        </button>\n                      );\n                    })}\n                  </div>\n                  <p className="calendar__selected-note">{date ? `Selected: ${dateLabel}` : "No date selected yet."}</p>\n                </div>\n              </div>\n            )}\n\n            {step === 3 && (\n              <div className="booking__step is-active">\n                <p className="eyebrow booking__kicker">Step 03</p>\n                <h1 className="h3 booking__title">Your experience.</h1>\n                <div className="service-select">\n                  {SERVICES.map((s) => (\n                    <div key={s.title} className={`service-option${service === s.title ? " is-selected" : ""}`} role="radio" aria-checked={service === s.title} tabIndex={0} onClick={() => setService(s.title)}>\n                      <div className="service-option__left">\n                        <span className="service-option__radio"></span>\n                        <div><p className="service-option__name">{s.title}</p><p className="service-option__desc">{s.desc}</p></div>\n                      </div>\n                      <span className="service-option__price">Price on consultation</span>\n                    </div>\n                  ))}\n                </div>\n              </div>\n            )}\n\n            {step === 4 && (\n              <div className="booking__step is-active">\n                <p className="eyebrow booking__kicker">Step 04</p>\n                <h1 className="h3 booking__title">Tell us about your moment.</h1>\n                <div className="form-grid">\n                  <div className="field"><label htmlFor="bkName">Full name</label><input id="bkName" required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></div>\n                  <div className="field"><label htmlFor="bkEmail">Email</label><input id="bkEmail" type="email" required value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} /></div>\n                  <div className="field"><label htmlFor="bkPhone">Phone number</label><input id="bkPhone" type="tel" required value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} /></div>\n                  <div className="field"><label htmlFor="bkTime">Preferred time</label><input id="bkTime" type="time" value={form.time} onChange={(e) => setForm({ ...form, time: e.target.value })} /></div>\n                  <div className="field"><label htmlFor="bkLocation">Event location</label><input id="bkLocation" placeholder="e.g. Venue, borough or postcode" required value={form.location} onChange={(e) => setForm({ ...form, location: e.target.value })} /></div>\n                  <div className="field"><label htmlFor="bkPeople">Number of people</label><input id="bkPeople" type="number" min="1" value={form.people} onChange={(e) => setForm({ ...form, people: e.target.value })} /></div>\n                  <div className="field field--full"><label htmlFor="bkNotes">Additional notes</label><textarea id="bkNotes" placeholder="Outfit colour, inspiration images, anything we should know." value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })}></textarea></div>\n                </div>\n                {formError && <p className="field__hint" style={{ color: "var(--burgundy)", marginTop: "1rem" }}>Please fill in your name, email, phone and location to continue.</p>}\n              </div>\n            )}\n\n            {step === 5 && (\n              <div className="booking__step is-active">\n                <p className="eyebrow booking__kicker">Step 05</p>\n                <h1 className="h3 booking__title">Review your request.</h1>\n                <dl className="review-list">\n                  {[["Occasion", occasion], ["Date", dateLabel], ["Experience", service], ["Name", form.name], ["Email", form.email], ["Phone", form.phone], ["Location", form.location], ["Number of people", form.people], ["Preferred time", form.time], ["Notes", form.notes]].map(([k, v]) => (\n                    <div key={k} className="review-row"><dt>{k}</dt><dd>{v || "—"}</dd></div>\n                  ))}\n                </dl>\n                <p className="field__hint" style={{ marginBottom: "2rem", maxWidth: "52ch" }}>This sends a request, not a confirmed appointment. Gele Glamzzz will reply to confirm availability.</p>\n                {submitError && <p className="field__hint" style={{ color: "var(--burgundy)", marginBottom: "1rem" }}>{submitError}</p>}\n              </div>\n            )}\n\n            <div className="booking__nav" style={step === 1 ? { justifyContent: "flex-end" } : undefined}>\n              {step > 1 && <button className="booking__back" onClick={() => goTo(step - 1)}>← Back</button>}\n              {step < 5 && <button className="btn btn--primary" disabled={!canContinue} onClick={handleNext}>Continue <span className="btn__arrow">→</span></button>}\n              {step === 5 && <button className="btn btn--primary" onClick={handleSubmit} disabled={submitting}>{submitting ? "Sending…" : "Request my appointment"} <span className="btn__arrow">→</span></button>}\n            </div>\n          </>\n        )}\n\n        {submitted && (\n          <div className="booking__success is-active">\n            <div className="booking__success-inner">\n              <p className="eyebrow" style={{ marginBottom: "1.4rem" }}>Request Received</p>\n              <h1 className="display-2" style={{ marginBottom: "1.6rem" }}>Your moment<br />has been reserved<span className="accent-dot">.</span></h1>\n              <p className="lede" style={{ marginBottom: "2.4rem" }}>Thank you. Your request has been received. We&apos;ll be in touch shortly to confirm your appointment.</p>\n              <a href="/" className="btn btn--ghost" onClick={(e) => { e.preventDefault(); resetAll(); if (window.__navigateWithTransition) window.__navigateWithTransition("/"); else window.location.href = "/"; }}>Return home</a>\n            </div>\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n');
write('components/ContactClient.js', '"use client";\nimport { useState } from "react";\nimport useReveal from "@/lib/useReveal";\n\nexport default function ContactClient() {\n  useReveal();\n  const [form, setForm] = useState({ name: "", email: "", message: "" });\n  const [status, setStatus] = useState("idle"); // idle | sending | sent | error\n  const [errorMsg, setErrorMsg] = useState("");\n\n  async function handleSubmit(e) {\n    e.preventDefault();\n    setStatus("sending");\n    setErrorMsg("");\n    try {\n      const res = await fetch("/api/contact", {\n        method: "POST",\n        headers: { "Content-Type": "application/json" },\n        body: JSON.stringify(form),\n      });\n      const data = await res.json();\n      if (!res.ok) {\n        setErrorMsg(data.error || "Something went wrong. Please try again.");\n        setStatus("error");\n        return;\n      }\n      setStatus("sent");\n    } catch {\n      setErrorMsg("Could not reach the server. Please check your connection and try again.");\n      setStatus("error");\n    }\n  }\n\n  return (\n    <>\n      <section className="page-hero">\n        <div className="page-hero__media">\n          <img src="/images/testimonial-portrait.jpg" alt="Client in a beaded pink gown and matching gele" loading="eager" />\n        </div>\n        <div className="page-hero__scrim" aria-hidden="true"></div>\n        <div className="page-hero__content">\n          <span className="eyebrow" data-reveal style={{ color: "var(--gold-soft)" }}>Get In Touch</span>\n          <h1 className="display-2" data-reveal style={{ marginTop: ".6rem" }}>Let&apos;s start<br />the conversation.</h1>\n        </div>\n      </section>\n\n      <section className="contact-split">\n        <div className="contact-split__media media-frame" data-reveal-scale>\n          <div className="media-frame__art"><img src="/images/story-heritage.jpg" alt="Client in a silver holographic gele and beaded pale blue gown" loading="lazy" /></div>\n          <div className="contact-split__media-quote">\n            <p>&ldquo;Every message gets a real reply, from a real person, not a queue.&rdquo;</p>\n          </div>\n        </div>\n\n        <div className="contact-split__body">\n          <div data-reveal>\n            <span className="eyebrow">Reach Us</span>\n            <h2 className="h3" style={{ marginTop: ".6rem" }}>Questions about a service,<br />a class, or something bespoke.</h2>\n          </div>\n\n          <div className="contact-methods" data-reveal>\n            <div className="contact-methods__item">\n              <span className="contact-methods__num">01</span>\n              <h4>Email</h4>\n              <a href="mailto:hello@geleglamzzz.com" className="text-link" data-placeholder-link>hello@geleglamzzz.com</a>\n            </div>\n            <div className="contact-methods__item">\n              <span className="contact-methods__num">02</span>\n              <h4>Instagram</h4>\n              <a href="https://www.instagram.com/geleglamzzz/" className="text-link" target="_blank" rel="noopener noreferrer">@geleglamzzz</a>\n            </div>\n            <div className="contact-methods__item">\n              <span className="contact-methods__num">03</span>\n              <h4>Studio</h4>\n              <span className="body-copy" style={{ margin: 0 }}>London, UK — also available to travel, UK &amp; international</span>\n            </div>\n          </div>\n\n          <div className="contact-split__form-card" data-reveal>\n            {status !== "sent" ? (\n              <form onSubmit={handleSubmit}>\n                <div className="form-grid">\n                  <div className="field field--full">\n                    <label htmlFor="cName">Full name</label>\n                    <input id="cName" required disabled={status === "sending"} value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />\n                  </div>\n                  <div className="field field--full">\n                    <label htmlFor="cEmail">Email</label>\n                    <input id="cEmail" type="email" required disabled={status === "sending"} value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} />\n                  </div>\n                  <div className="field field--full">\n                    <label htmlFor="cMessage">Message</label>\n                    <textarea id="cMessage" required rows={4} disabled={status === "sending"} value={form.message} onChange={(e) => setForm({ ...form, message: e.target.value })}></textarea>\n                  </div>\n                </div>\n                {status === "error" && <p className="field__hint" style={{ color: "var(--burgundy)", marginTop: "1rem" }}>{errorMsg}</p>}\n                <button type="submit" className="btn btn--primary" disabled={status === "sending"} style={{ marginTop: "1.6rem" }}>\n                  {status === "sending" ? "Sending…" : "Send message"} <span className="btn__arrow">→</span>\n                </button>\n              </form>\n            ) : (\n              <div>\n                <p className="h3" style={{ marginBottom: ".8rem" }}>Message sent<span className="accent-dot">.</span></p>\n                <p className="body-copy">Thank you, we&apos;ll get back to you shortly.</p>\n              </div>\n            )}\n          </div>\n        </div>\n      </section>\n    </>\n  );\n}\n');
write('lib/data.js', "export const FEATURED_WORK = [\n  { num: '01', title: 'The Bridal Crown', desc: 'A refined finishing statement for the bride who wants presence without excess.', grad: 'linear-gradient(200deg,#3a2a1c,#15100c)', line: '#caa877', sym: 'fold-a' },\n  { num: '02', title: 'The Royal Fold', desc: 'Architectural, high and unmistakably regal. Our most requested signature shape.', grad: 'linear-gradient(200deg,#5c2231,#2b2018)', line: '#d7ab6e', sym: 'fold-b' },\n  { num: '03', title: 'The Statement', desc: 'Bold volume and colour play, built for a moment that should not be missed.', grad: 'linear-gradient(200deg,#a6522e,#15100c)', line: '#f2e9d8', sym: 'fold-c' },\n  { num: '04', title: 'The Editorial', desc: 'Sculptural and campaign ready, for photography that needs to hold a frame.', grad: 'linear-gradient(200deg,#8a6b45,#2b2018)', line: '#f2e9d8', sym: 'fold-a' },\n];\n\nexport const SERVICES = [\n  { tag: 'Bridal', title: 'Bridal Gele', desc: 'For brides who want an unforgettable finishing statement.', grad: 'linear-gradient(200deg,#3a2a1c,#15100c)', line: '#caa877', sym: 'fold-a', img: '/images/gele-pink-dramatic-2.jpg' },\n  { tag: 'Heritage', title: 'Traditional Ceremonies', desc: 'Beautiful gele styling for cultural celebrations.', grad: 'linear-gradient(200deg,#5c2231,#2b2018)', line: '#d7ab6e', sym: 'fold-b', img: '/images/gele-blue-asooke-1.jpg' },\n  { tag: 'Celebration', title: 'Special Occasions', desc: 'Birthdays, parties and milestone moments.', grad: 'linear-gradient(200deg,#a6522e,#15100c)', line: '#f2e9d8', sym: 'fold-c', img: '/images/gele-peach-2.jpg' },\n  { tag: 'Editorial', title: 'Photoshoots', desc: 'Editorial and creative styling built for the camera.', grad: 'linear-gradient(200deg,#8a6b45,#15100c)', line: '#f2e9d8', sym: 'fold-a', img: '/images/gele-silver-editorial-4.jpg' },\n  { tag: 'Corporate', title: 'Corporate Workshops', desc: 'Team-building and culture events, gele styling and tying sessions for offices and organisations.', grad: 'linear-gradient(200deg,#2b2018,#15100c)', line: '#dac49c', sym: 'fold-b', img: '/images/gele-white-beaded-1.jpg' },\n];\n\nexport const PROCESS = [\n  { num: '01', title: 'Consult', body: 'We discover your vision, your event and the story you want your look to tell.' },\n  { num: '02', title: 'Prepare', body: 'We consider your outfit, event, face shape and desired aesthetic in detail.' },\n  { num: '03', title: 'Create', body: 'Your gele is carefully sculpted, folded and perfected by hand.' },\n  { num: '04', title: 'Crown', body: 'You step into your moment, ready and unforgettable.' },\n];\n\nexport const TESTIMONIALS = [\n  { quote: 'She completely transformed my look. The gele was the final piece that made everything come together.', who: 'Bridal Client, London', img: '/images/gele-pink-beaded-3.jpg', alt: 'Client in a beaded pink gown and matching gele' },\n  { quote: 'Every fold was so precise. I felt like I was wearing a piece of art, not just fabric.', who: 'Traditional Ceremony Client', img: '/images/gele-silver-editorial-5.jpg', alt: 'Client in a silver editorial gele and gown' },\n  { quote: 'Effortless from the first message to the final touch. I have never felt more put together.', who: 'Corporate Workshop Client, London', img: '/images/gele-peach-1.jpg', alt: 'Client in a peach gele and matching gown' },\n];\n\nexport const INSTAGRAM = [\n  { img: '/images/insta-mint-veil.jpg', alt: 'Client in a mint green traditional look with matching gele and veil' },\n  { img: '/images/insta-podcast.jpg', alt: 'Gele Glamzzz styling featured on a podcast appearance' },\n  { img: '/images/insta-glam-gold.jpg', alt: 'Client in a gold and yellow patterned gele' },\n  { img: '/images/insta-mint-pose.jpg', alt: 'Client in a mint green traditional look with matching gele' },\n  { img: '/images/insta-glam-white.jpg', alt: 'Client in a white gele with beaded gold-fringe gown' },\n];\n\n/* Journal, reimagined as a pictures + video feed.\n   TODO(video): each { type:'video' } entry below has no `src` yet — drop an\n   .mp4 file into /public/videos/ and set its src (see JournalScripts.js,\n   nothing else needs to change; it autoplays muted, looped, no controls). */\nexport const JOURNAL_MEDIA = [\n  { type: 'video', src: '', poster: '/images/gele-pink-dramatic-1.jpg', caption: 'The Full Look', sub: 'Video', suggest: 'journal-full-look.mp4' },\n  { type: 'image', src: '/images/gele-pink-beaded-2.jpg', caption: 'The Beaded Fold', sub: 'Bridal' },\n  { type: 'image', src: '/images/gele-silver-editorial-3.jpg', caption: 'The Silver Fold', sub: 'Editorial' },\n  { type: 'video', src: '', poster: '/images/gele-silver-editorial-2.jpg', caption: 'Behind the Fold', sub: 'Video', suggest: 'journal-behind-the-fold.mp4' },\n  { type: 'image', src: '/images/vogue-backstage.jpg', caption: 'Backstage, Fashion Week', sub: 'Runway' },\n  { type: 'image', src: '/images/gele-silver-editorial-1.jpg', caption: 'Texture Study', sub: 'Detail' },\n  { type: 'video', src: '', poster: '/images/gele-pink-beaded-1.jpg', caption: 'A Client Reveal', sub: 'Video', suggest: 'journal-reveal.mp4' },\n  { type: 'image', src: '/images/gele-blue-asooke-2.jpg', caption: 'Aso-Oke Edit', sub: 'London' },\n  { type: 'image', src: '/images/gele-white-beaded-2.jpg', caption: 'Hand-Finished Detail', sub: 'Bridal' },\n  { type: 'image', src: '/images/gele-mint-closeup.jpg', caption: 'The Mint Wrap', sub: 'Detail' },\n  { type: 'image', src: '/images/gele-ceremony-moment.jpg', caption: 'A Traditional Ceremony', sub: 'London' },\n];\n");
write('.env.local.example', '# Copy this file to .env.local and fill in the two values below.\n# .env.local is already in .gitignore, so it will never be committed or\n# pushed to GitHub — that\'s exactly what you want for a secret API key.\n\n# 1. Sign up free at https://resend.com (no credit card required for the\n#    free tier: 100 emails/day, 3,000/month, plenty for a contact/booking form).\n# 2. Create an API key: Dashboard -> API Keys -> Create API Key.\n# 3. Paste it here:\nRESEND_API_KEY=re_your_api_key_here\n\n# 4. The email address YOU want to receive contact and booking messages at.\n#    This can be any real inbox you check — Gmail, Outlook, whatever you use.\nCONTACT_TO_EMAIL=you@example.com\n\n# That\'s it — both forms are already wired up to use these. After setting\n# them, restart the dev server (Ctrl+C, then npm run dev) so Next.js picks\n# up the new values.\n#\n# One more step for when you deploy (e.g. to Vercel): add these same two\n# variables in your hosting provider\'s dashboard under\n# Project Settings -> Environment Variables, since .env.local only works\n# locally and is never uploaded anywhere.\n#\n# Note on the sender address: emails currently send from\n# "onboarding@resend.dev", Resend\'s shared testing address, which works\n# immediately with no setup. If you want emails to instead say\n# "from @geleglamzzz.com", that requires verifying your domain in the\n# Resend dashboard (Domains -> Add Domain) and adding a few DNS records —\n# not required to get started, just an option later for a more polished\n# sender name.\n');
write('app/api/contact/route.js', 'import { Resend } from "resend";\n\n// A simple in-memory rate limiter — resets on server restart. Blocks a burst\n// of spam from the same IP without needing a database. Fine for a site this\n// size; if traffic grows, this would want a proper store (e.g. Redis).\nconst submissions = new Map();\nconst WINDOW_MS = 10 * 60 * 1000; // 10 minutes\nconst MAX_PER_WINDOW = 5;\n\nfunction isRateLimited(ip) {\n  const now = Date.now();\n  const timestamps = (submissions.get(ip) || []).filter((t) => now - t < WINDOW_MS);\n  timestamps.push(now);\n  submissions.set(ip, timestamps);\n  return timestamps.length > MAX_PER_WINDOW;\n}\n\nexport async function POST(request) {\n  try {\n    const ip = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() || "unknown";\n    if (isRateLimited(ip)) {\n      return Response.json({ error: "Too many messages sent recently. Please try again later." }, { status: 429 });\n    }\n\n    const { name, email, message } = await request.json();\n\n    if (!name || !email || !message) {\n      return Response.json({ error: "Please fill in every field." }, { status: 400 });\n    }\n    const emailPattern = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;\n    if (!emailPattern.test(email)) {\n      return Response.json({ error: "Please enter a valid email address." }, { status: 400 });\n    }\n\n    if (!process.env.RESEND_API_KEY || !process.env.CONTACT_TO_EMAIL) {\n      console.error("Contact form: missing RESEND_API_KEY or CONTACT_TO_EMAIL env vars");\n      return Response.json({ error: "The contact form is not fully configured yet. Please email directly instead." }, { status: 500 });\n    }\n\n    const resend = new Resend(process.env.RESEND_API_KEY);\n    const { error } = await resend.emails.send({\n      from: "Gele Glamzzz Website <onboarding@resend.dev>",\n      to: process.env.CONTACT_TO_EMAIL,\n      replyTo: email,\n      subject: `New website enquiry from ${name}`,\n      text: `New message from the Gele Glamzzz contact form.\\n\\nName: ${name}\\nEmail: ${email}\\n\\nMessage:\\n${message}`,\n      html: `<h2>New website enquiry</h2><p><strong>Name:</strong> ${escapeHtml(name)}</p><p><strong>Email:</strong> ${escapeHtml(email)}</p><p><strong>Message:</strong></p><p>${escapeHtml(message).replace(/\\n/g, "<br>")}</p>`,\n    });\n\n    if (error) {\n      console.error("Resend error (contact):", error);\n      return Response.json({ error: "Something went wrong sending your message. Please try again." }, { status: 500 });\n    }\n\n    return Response.json({ success: true });\n  } catch (err) {\n    console.error("Contact form error:", err);\n    return Response.json({ error: "Something went wrong. Please try again." }, { status: 500 });\n  }\n}\n\nfunction escapeHtml(str) {\n  return String(str).replace(/[&<>"\']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", \'"\': "&quot;", "\'": "&#39;" }[c]));\n}\n');
write('app/api/booking/route.js', 'import { Resend } from "resend";\n\nconst submissions = new Map();\nconst WINDOW_MS = 10 * 60 * 1000;\nconst MAX_PER_WINDOW = 5;\n\nfunction isRateLimited(ip) {\n  const now = Date.now();\n  const timestamps = (submissions.get(ip) || []).filter((t) => now - t < WINDOW_MS);\n  timestamps.push(now);\n  submissions.set(ip, timestamps);\n  return timestamps.length > MAX_PER_WINDOW;\n}\n\nexport async function POST(request) {\n  try {\n    const ip = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() || "unknown";\n    if (isRateLimited(ip)) {\n      return Response.json({ error: "Too many requests sent recently. Please try again later." }, { status: 429 });\n    }\n\n    const { occasion, dateLabel, serviceTitle, form } = await request.json();\n\n    if (!occasion || !dateLabel || !serviceTitle || !form?.name || !form?.email || !form?.phone || !form?.location) {\n      return Response.json({ error: "Please fill in every required field." }, { status: 400 });\n    }\n    const emailPattern = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;\n    if (!emailPattern.test(form.email)) {\n      return Response.json({ error: "Please enter a valid email address." }, { status: 400 });\n    }\n\n    if (!process.env.RESEND_API_KEY || !process.env.CONTACT_TO_EMAIL) {\n      console.error("Booking form: missing RESEND_API_KEY or CONTACT_TO_EMAIL env vars");\n      return Response.json({ error: "The booking form is not fully configured yet. Please email directly instead." }, { status: 500 });\n    }\n\n    const lines = [\n      `Occasion: ${occasion}`,\n      `Requested date: ${dateLabel}`,\n      `Time: ${form.time || "Not specified"}`,\n      `Service: ${serviceTitle}`,\n      `Name: ${form.name}`,\n      `Email: ${form.email}`,\n      `Phone: ${form.phone}`,\n      `Location: ${form.location}`,\n      `Number of people: ${form.people || 1}`,\n      `Notes: ${form.notes || "None"}`,\n    ];\n\n    const resend = new Resend(process.env.RESEND_API_KEY);\n    const { error } = await resend.emails.send({\n      from: "Gele Glamzzz Website <onboarding@resend.dev>",\n      to: process.env.CONTACT_TO_EMAIL,\n      replyTo: form.email,\n      subject: `New booking request — ${occasion} — ${form.name}`,\n      text: `New booking request from the Gele Glamzzz website.\\n\\n${lines.join("\\n")}\\n\\nThis is a request, not a confirmed appointment. Reply directly to ${form.email} to confirm.`,\n      html: `<h2>New booking request</h2><ul>${lines.map((l) => `<li>${escapeHtml(l)}</li>`).join("")}</ul><p>This is a request, not a confirmed appointment. Reply directly to confirm.</p>`,\n    });\n\n    if (error) {\n      console.error("Resend error (booking):", error);\n      return Response.json({ error: "Something went wrong sending your request. Please try again." }, { status: 500 });\n    }\n\n    return Response.json({ success: true });\n  } catch (err) {\n    console.error("Booking form error:", err);\n    return Response.json({ error: "Something went wrong. Please try again." }, { status: 500 });\n  }\n}\n\nfunction escapeHtml(str) {\n  return String(str).replace(/[&<>"\']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", \'"\': "&quot;", "\'": "&#39;" }[c]));\n}\n');

const IMAGES = {
  "ayra-starr-x-buzz.jpg": "",
  "gele-ceremony-moment.jpg": "",
  "gele-mint-closeup.jpg": "",
};

const imagesDir = path.join(root, "public", "images");
fs.mkdirSync(imagesDir, { recursive: true });
for (const [name, b64] of Object.entries(IMAGES)) {
  fs.writeFileSync(path.join(imagesDir, name), Buffer.from(b64, "base64"));
  console.log("✓ wrote public/images/" + name);
}

fs.mkdirSync(path.join(root, "public", "videos", "podcast"), { recursive: true });
console.log("✓ created public/videos/podcast/ — drop your podcast video file in there whenever you have it");

console.log("\nInstalling resend...");
try {
  execSync("npm install resend", { cwd: root, stdio: "inherit" });
  console.log("✓ resend installed");
} catch {
  console.error("✖ npm install failed — run `npm install resend` yourself, everything else is already in place.");
}

console.log("\nDone. Next steps:");
console.log("1. Copy .env.local.example to .env.local and fill in your Resend API key + your real email");
console.log("2. Restart the dev server (Ctrl+C, then npm run dev)");
